window.DL_LADDERS = Object.assign(window.DL_LADDERS || {}, {"e5-1|1. 자연수의 혼합 계산|01. 덧셈과 뺄셈 / 곱셈과 나눗셈이 섞인 식": [{"kind": "방법", "q": "덧셈과 뺄셈이 섞여 있는 식은 어떤 순서로 계산해야 돼? 곱셈과 나눗셈이 섞여 있는 식도 얘기해 봐.", "ideas": [["덧셈과 뺄셈만 섞여 있으면 앞에서부터 차례로 계산한다", "17−6+3 에서 뒤에 있는 6+3 을 먼저 계산해도 돼?"], ["곱셈과 나눗셈만 섞여 있어도 앞에서부터 차례로 계산한다", "12÷2×3 은 어느 쪽부터 계산해야 돼?"]], "teach": "덧셈과 뺄셈끼리 섞이면 앞에서부터 차례로 계산해. 곱셈과 나눗셈끼리 섞여도 똑같이 앞에서부터야. 17−6+3 은 17−6 을 먼저 하고, 12÷2×3 은 12÷2 를 먼저 해.", "again": "30÷5×2 는 어느 쪽부터 계산해야 돼? 그렇게 하는 규칙도 같이 말해 봐.", "fig": false, "src": "8쪽", "miscon": "덧셈·뺄셈끼리 또는 곱셈·나눗셈끼리만 섞인 식에서도 뒤쪽을 먼저 계산해도 된다고 생각함", "record": "덧셈·뺄셈끼리, 곱셈·나눗셈끼리 섞인 식은 앞에서부터 차례로 계산한다는 규칙을 말하지 못함"}, {"kind": "함정", "q": "17−(6+3) 처럼 괄호가 있는 식은 어디부터 계산해야 돼? 괄호가 없는 17−6+3 이랑 결과가 같은지 다른지도 말해 봐.", "ideas": [["괄호가 있으면 괄호 안을 가장 먼저 계산한다", "괄호는 '여기를 먼저 계산하라'는 표시야, 아니면 그냥 묶어 둔 표시야?"], ["괄호 때문에 계산하는 차례가 달라지므로 결과도 달라진다", "계산하는 차례가 바뀌면 답은 어떻게 돼?"]], "teach": "괄호가 있으면 괄호 안을 가장 먼저 계산해. 17−6+3 은 앞에서부터라 17−6 을 먼저 하지만, 17−(6+3) 은 6+3 을 먼저 해. 차례가 달라서 결과도 달라져.", "again": "12÷(2×3) 은 어디를 먼저 계산해야 돼? 괄호가 없는 12÷2×3 이랑 결과가 같은지도 말해 봐.", "fig": false, "src": "8쪽", "miscon": "괄호를 '먼저 계산하라'는 표시가 아니라 단순히 묶어 둔 표시로 봄", "record": "괄호 안을 먼저 계산한다는 것은 알지만, 괄호 때문에 결과가 달라진다는 것을 설명하지 못함"}, {"kind": "이유", "q": "12÷2×3 을 앞에서부터 안 하고 2×3 을 먼저 계산하면 왜 안 돼?", "ideas": [["2×3 을 먼저 하면 12 를 6 으로 나누는 다른 식이 되어 버린다", "2×3 을 먼저 하면 12 를 뭐로 나누는 셈이 돼?"], ["정말 그렇게 계산하려면 12÷(2×3) 처럼 괄호로 묶어 줘야 한다", "2×3 을 먼저 하고 싶으면 식을 어떻게 고쳐 써야 돼?"]], "teach": "12÷2×3 은 12 를 2 로 나눈 다음 3 을 곱하라는 뜻이야. 2×3 을 먼저 하면 12 를 6 으로 나누는 완전히 다른 식이 돼. 정말 그렇게 하고 싶으면 12÷(2×3) 처럼 괄호로 묶어야 해.", "again": "24÷4×2 에서 4×2 를 먼저 계산하고 싶어. 식을 어떻게 고쳐 써야 돼?", "fig": false, "src": "8쪽", "miscon": "곱셈이 나눗셈보다 먼저라고 생각해 앞에서부터 계산하는 규칙을 어김", "record": "곱셈·나눗셈이 섞인 식에서 계산 차례를 바꾸면 다른 식이 된다는 것을 이해하지 못함"}], "e5-1|1. 자연수의 혼합 계산|02. 덧셈·뺄셈·곱셈(나눗셈)이 섞인 식": [{"kind": "방법", "q": "20+9×5−8 처럼 덧셈, 뺄셈, 곱셈이 섞여 있는 식은 뭐부터 계산해야 돼?", "ideas": [["곱셈을 가장 먼저 계산한다", "20+9 랑 9×5 중에 어느 쪽이 먼저야?"], ["곱셈을 끝낸 뒤 남은 덧셈과 뺄셈은 앞에서부터 차례로 계산한다", "곱셈을 다 하고 나면 남은 덧셈·뺄셈은 어떤 순서로 해야 돼?"]], "teach": "덧셈·뺄셈에 곱셈이 섞여 있으면 곱셈을 먼저 계산해. 20+9×5−8 이면 9×5 를 먼저 하고, 남은 20+45−8 을 앞에서부터 차례로 해. 나눗셈이 섞인 30+56÷2−25 도 나눗셈을 먼저 계산해.", "again": "40−12÷4+7 은 뭘 가장 먼저 계산해야 돼? 그 다음 순서도 말해 봐.", "fig": false, "src": "10쪽", "miscon": "덧셈·뺄셈에 곱셈(나눗셈)이 섞여 있어도 무조건 앞에서부터 계산한다고 생각함", "record": "곱셈(나눗셈)을 먼저 계산한다는 규칙을 말하지 못하거나, 남은 덧셈·뺄셈은 앞에서부터 한다는 것을 빠뜨림"}, {"kind": "함정", "q": "(20+9)×5−8 은 괄호, 곱셈, 덧셈·뺄셈 중에 뭘 먼저 계산해야 돼? 차례대로 말해 봐.", "ideas": [["괄호 안을 가장 먼저 계산한다", "곱셈보다도 먼저 계산해야 하는 게 있어?"], ["괄호 안을 끝낸 다음 곱셈, 그 다음 덧셈과 뺄셈 순서로 계산한다", "괄호 안을 다 했으면 남은 것 중에 뭐가 먼저야?"]], "teach": "순서는 괄호 안 → 곱셈(나눗셈) → 덧셈·뺄셈이야. (20+9)×5−8 이면 20+9 를 먼저, 그 다음 29×5, 마지막에 145−8 을 계산해.", "again": "(30+56)÷2−25 는 어떤 차례로 계산해야 돼? 순서를 차례대로 말해 봐.", "fig": false, "src": "10쪽", "miscon": "괄호보다 곱셈이 먼저라고 생각함", "record": "괄호 안 → 곱셈(나눗셈) → 덧셈·뺄셈의 순서를 차례대로 설명하지 못함"}, {"kind": "적용", "q": "'공책 50권을 사서 여학생 12명과 남학생 8명에게 2권씩 나누어 줬어. 남은 공책은 몇 권일까?' 이걸 하나의 식으로 어떻게 쓰는지 얘기해 봐. 계산은 안 해도 돼.", "ideas": [["나누어 준 학생 수 12+8 을 먼저 구해야 하므로 괄호로 묶는다", "학생 수를 먼저 구해야 하는데, 그 부분을 식에서 어떻게 표시해?"], ["50−(12+8)×2 처럼 하나의 식으로 이어 쓴다", "'50권에서 나누어 준 공책 수를 뺀다'를 식으로 어떻게 이어 써?"]], "teach": "먼저 계산해야 하는 부분을 괄호로 묶으면 하나의 식으로 쓸 수 있어. 학생이 12+8 명이고 한 명에게 2권씩이니까 나누어 준 공책은 (12+8)×2 권, 남은 공책은 50−(12+8)×2 권이야.", "again": "'쑥떡 10개랑 콩떡 6개를 접시 4개에 똑같이 나누어 담았어. 한 접시에서 3개를 먹었다면 남은 떡은 몇 개일까?' 를 하나의 식으로 어떻게 쓰는지 말해 봐. 계산은 안 해도 돼.", "fig": false, "src": "10쪽", "miscon": "문장을 하나의 식으로 옮길 때 먼저 계산해야 하는 부분을 괄호로 묶지 않음", "record": "상황을 하나의 식으로 나타낼 때 먼저 계산할 부분을 괄호로 묶어야 한다는 것을 적용하지 못함"}], "e5-1|1. 자연수의 혼합 계산|03. 덧셈·뺄셈·곱셈·나눗셈이 섞인 식": [{"kind": "방법", "q": "9+12÷3×2−10 처럼 덧셈, 뺄셈, 곱셈, 나눗셈이 다 섞여 있는 식은 어떤 순서로 계산해야 돼?", "ideas": [["곱셈과 나눗셈을 덧셈·뺄셈보다 먼저 계산한다", "덧셈·뺄셈이랑 곱셈·나눗셈 중에 어느 쪽이 먼저야?"], ["곱셈과 나눗셈끼리는 앞에서부터 차례로 계산한다", "12÷3 이랑 3×2 중에 뭘 먼저 해야 돼?"]], "teach": "네 가지가 다 섞이면 곱셈과 나눗셈을 먼저 하고, 그 곱셈·나눗셈끼리는 앞에서부터 차례로 계산해. 9+12÷3×2−10 이면 12÷3 을 먼저, 그 다음 4×2, 마지막에 9+8−10 을 앞에서부터 계산해.", "again": "30−8×3+16÷4 에서 먼저 계산해야 하는 게 뭐야? 그것들 사이의 순서도 말해 봐.", "fig": false, "src": "12쪽", "miscon": "곱셈·나눗셈을 먼저 한다는 것은 알지만, 그 둘 사이에서 곱셈을 항상 먼저 한다고 생각함", "record": "곱셈·나눗셈을 먼저 한다는 것은 알지만, 곱셈과 나눗셈끼리는 앞에서부터 차례로 한다는 것을 설명하지 못함"}, {"kind": "함정", "q": "(9+12)÷3×2−10 이랑 9+12÷(3×2)−10 은 괄호 위치만 다른데, 계산 결과가 같아, 달라? 왜 그런지도 말해 봐.", "ideas": [["괄호 안을 가장 먼저 계산하므로 괄호 위치가 바뀌면 먼저 계산하는 부분이 달라진다", "괄호가 어디 있느냐에 따라 뭐가 달라져?"], ["먼저 계산하는 부분이 달라지면 결과도 달라진다", "계산하는 차례가 달라지면 답은 어떻게 돼?"]], "teach": "괄호 안을 가장 먼저 계산하니까, 괄호를 어디에 치느냐에 따라 먼저 계산하는 부분이 달라져. 그래서 (9+12)÷3×2−10 과 9+12÷(3×2)−10 은 결과가 서로 달라.", "again": "24÷6×2 에 괄호를 쳐서 (24÷6)×2 랑 24÷(6×2) 를 만들었어. 두 결과가 같을지 다를지 이유랑 같이 말해 봐.", "fig": false, "src": "12쪽", "miscon": "괄호는 위치가 달라도 결과에 영향을 주지 않는다고 생각함", "record": "괄호의 위치에 따라 먼저 계산하는 부분과 결과가 달라진다는 것을 설명하지 못함"}, {"kind": "이유", "q": "9+12÷3×2−10 에서 12÷3 만 괄호로 묶어서 9+(12÷3)×2−10 이라고 썼어. 결과가 달라져? 이유도 말해 봐.", "ideas": [["괄호를 치기 전에도 12÷3 을 가장 먼저 계산했으므로 계산 차례가 바뀌지 않는다", "괄호를 치기 전에는 뭘 가장 먼저 계산했어?"], ["계산 차례가 그대로이므로 결과도 같다", "계산하는 차례가 안 바뀌면 답은 어떻게 돼?"]], "teach": "괄호는 계산 차례를 바꿀 때 힘을 써. 9+12÷3×2−10 은 원래도 12÷3 을 가장 먼저 계산하니까, 그 부분을 괄호로 묶어도 차례가 그대로여서 결과가 같아.", "again": "20+9×5−8 에서 9×5 를 괄호로 묶어서 20+(9×5)−8 이라고 쓰면 결과가 달라져? 이유랑 같이 말해 봐.", "fig": false, "src": "12쪽", "miscon": "괄호를 치기만 하면 무조건 결과가 달라진다고 생각함", "record": "괄호가 계산 차례를 바꿀 때만 결과가 달라진다는 것을 이해하지 못함"}], "e5-1|2. 약수와 배수|01. 약수와 배수": [{"kind": "뜻", "q": "어떤 수의 약수가 뭔지 말해 봐. 6의 약수를 어떻게 찾는지도 얘기해 봐.", "ideas": [["어떤 수를 나누어떨어지게 하는 수가 그 수의 약수다", "6÷4 는 나머지가 남는데, 그럼 4 는 6 의 약수야?"], ["6 을 1부터 차례로 나눠 보고 나누어떨어지는 수를 모으면 6의 약수다", "6의 약수를 빠뜨리지 않으려면 어떤 수부터 차례로 나눠 봐야 돼?"]], "teach": "약수는 어떤 수를 나누어떨어지게 하는 수야. 나머지가 0이 되어야 해. 6÷1=6, 6÷2=3, 6÷3=2, 6÷6=1 이 나누어떨어지니까 6의 약수는 1, 2, 3, 6 이야.", "again": "8의 약수를 어떻게 찾는지 방법을 말해 봐. 약수가 뭔지도 같이 얘기해 봐.", "fig": false, "src": "32쪽", "miscon": "'나누어떨어진다'는 조건을 빼고, 나누기만 하면 약수라고 생각함", "record": "약수를 '나누어떨어지게 하는 수'로 정의하지 못하거나, 1부터 차례로 나눠 빠짐없이 찾는 방법을 말하지 못함"}, {"kind": "뜻", "q": "어떤 수의 배수가 뭔지 말해 봐. 6의 배수는 어떻게 구해?", "ideas": [["어떤 수를 1배, 2배, 3배 … 한 수가 그 수의 배수다", "6 을 몇 배 한 수들을 배수라고 부를까?"], ["6×1, 6×2, 6×3 … 처럼 6단 곱셈구구로 구하면 된다", "6의 배수를 차례로 구하려면 어떤 곱셈을 하면 돼?"], ["가장 작은 배수는 1배 한 수, 곧 자기 자신이다", "6 을 1배 하면 얼마야? 그것도 6의 배수야?"]], "teach": "배수는 어떤 수를 1배, 2배, 3배 … 한 수야. 6의 배수는 6×1=6, 6×2=12, 6×3=18 … 처럼 6단 곱셈구구와 같아. 그래서 가장 작은 배수는 자기 자신인 6이야.", "again": "9의 배수는 어떻게 구하는지 말해 봐. 9의 배수 중에서 가장 작은 수가 뭔지도 얘기해 봐.", "fig": false, "src": "32쪽", "miscon": "자기 자신(1배)은 배수가 아니라고 생각해 가장 작은 배수를 2배 한 수로 봄", "record": "배수의 뜻은 말하지만 자기 자신도 배수(가장 작은 배수)라는 것을 빠뜨림"}, {"kind": "성질", "q": "어떤 수든 꼭 가지고 있는 약수가 두 개 있어. 뭔지 말해 봐. 왜 그런지도 얘기해 봐.", "ideas": [["1은 모든 수의 약수다. 어떤 수든 1로 나누면 나누어떨어지기 때문이다", "6 을 1로 나누면 나머지가 남아?"], ["자기 자신도 약수이고, 그 수의 약수 중에서 가장 크다", "6 을 6으로 나누면 어떻게 돼? 6보다 큰 수로 6을 나누면 나누어떨어질까?"]], "teach": "어떤 수든 1로 나누면 나누어떨어지니까 1은 모든 수의 약수야. 또 자기 자신으로 나눠도 1이 되어 나누어떨어지지. 자기보다 큰 수로는 나누어떨어질 수 없으니까 자기 자신이 가장 큰 약수야.", "again": "15의 약수 중에서 가장 큰 수랑 가장 작은 수가 각각 뭐야? 왜 그런지도 말해 봐.", "fig": false, "src": "32쪽", "miscon": "1과 자기 자신을 약수에서 빼고 생각함", "record": "1과 자기 자신이 항상 약수라는 성질을 말하지 못하거나, 그 이유를 나눗셈으로 설명하지 못함"}, {"kind": "이유", "q": "어떤 수의 약수는 셀 수 있는데 배수는 셀 수 없이 많아. 왜 그런지 말해 봐.", "ideas": [["약수는 그 수보다 클 수 없어서 개수가 정해져 있다", "6 보다 큰 수로 6 을 나누면 나누어떨어질 수 있어?"], ["배수는 몇 배든 계속 만들 수 있어서 끝이 없다", "6의 배수를 구하다가 더 이상 곱할 수 없는 때가 올까?"]], "teach": "약수는 그 수보다 클 수 없어. 6보다 큰 수로 6을 나누면 절대 나누어떨어지지 않으니까. 그래서 약수는 개수가 정해져 있어. 반대로 배수는 6×100, 6×1000 처럼 얼마든지 계속 만들 수 있어서 끝이 없어.", "again": "10의 약수는 다 셀 수 있는데 10의 배수는 왜 끝까지 다 쓸 수 없을까? 이유를 말해 봐.", "fig": false, "src": "32쪽", "miscon": "배수에도 가장 큰 것이 있다고 생각함", "record": "약수는 유한하고 배수는 끝이 없다는 것을, '그 수보다 클 수 없다 / 얼마든지 곱할 수 있다'로 설명하지 못함"}], "e5-1|2. 약수와 배수|02. 곱을 이용한 약수와 배수의 관계": [{"kind": "방법", "q": "12를 두 수의 곱으로 나타내면 12의 약수를 한꺼번에 찾을 수 있어. 어떻게 하는지 말해 봐.", "ideas": [["12=1×12, 2×6, 3×4 처럼 두 수의 곱으로 빠짐없이 나타낸다", "곱해서 12가 되는 두 수 짝을 몇 가지나 만들 수 있어?"], ["곱셈식에 나온 수들이 모두 12의 약수다", "1×12 와 2×6 과 3×4 에 나온 수들을 모으면 뭐가 돼?"]], "teach": "12를 두 수의 곱으로 빠짐없이 나타내면 12=1×12=2×6=3×4 야. 여기 나온 1, 2, 3, 4, 6, 12 가 전부 12의 약수야. 나눗셈을 일일이 하지 않아도 한 번에 찾을 수 있어.", "again": "18을 두 수의 곱으로 나타내서 18의 약수를 찾으려고 해. 어떻게 하는지 말해 봐.", "fig": false, "src": "34쪽", "miscon": "곱셈식에서 곱해지는 두 수가 약수라는 것을 모르고 결과만 본다", "record": "두 수의 곱으로 나타내는 것까지는 하지만, 곱셈식에 나온 수들이 모두 약수라는 것을 설명하지 못함"}, {"kind": "성질", "q": "12=3×4 라는 곱셈식 하나에서 누가 누구의 약수이고 배수인지 말해 봐.", "ideas": [["3과 4는 12의 약수다", "3과 4 를 곱해서 12가 되면, 12를 3으로 나눴을 때 어떻게 될까?"], ["12는 3의 배수이면서 4의 배수이기도 하다", "12는 3을 몇 배 한 수야? 4는 몇 배 한 수고?"]], "teach": "■=▲×● 꼴이면 ▲와 ●는 ■의 약수이고, ■는 ▲의 배수이면서 ●의 배수야. 12=3×4 니까 3과 4는 12의 약수, 12는 3의 배수이자 4의 배수야.", "again": "20=5×4 라는 곱셈식에서 약수와 배수를 어떻게 읽을 수 있는지 말해 봐.", "fig": false, "src": "34쪽", "miscon": "약수와 배수를 거꾸로 말함(큰 수를 약수라고 함)", "record": "곱셈식에서 약수와 배수의 방향을 거꾸로 알고 있거나, 한쪽만 말하고 다른 쪽을 빠뜨림"}, {"kind": "방법", "q": "60처럼 큰 수는 두 수의 곱만으로 약수를 다 찾기 어려워. 여러 수의 곱으로 나타내는 방법을 말해 봐.", "ideas": [["먼저 두 수의 곱으로 나타낸다", "60 을 먼저 어떤 두 수의 곱으로 써 볼 수 있어?"], ["그렇게 나온 수들을 다시 두 수의 곱으로 계속 쪼갠다", "60=6×10 에서 6과 10 을 더 쪼갤 수 있어?"]], "teach": "먼저 두 수의 곱으로 쓰고, 그 수들을 다시 두 수의 곱으로 계속 쪼개면 돼. 60=6×10 이고 6=2×3, 10=2×5 니까 60=2×3×2×5 야. 더 이상 쪼갤 수 없을 때까지 하는 거야.", "again": "40을 여러 수의 곱으로 나타내려면 어떤 차례로 쪼개야 할까? 말해 봐.", "fig": false, "src": "34쪽", "miscon": "한 번만 쪼개고 더 쪼갤 수 있는데도 멈춤", "record": "여러 수의 곱으로 나타낼 때 더 쪼갤 수 없을 때까지 계속 쪼개야 한다는 것을 설명하지 못함"}, {"kind": "적용", "q": "18과 3이 약수와 배수의 관계인지 아닌지 어떻게 확인해? 나눗셈으로 말해 봐.", "ideas": [["큰 수를 작은 수로 나눠 본다", "18과 3 중에 어느 쪽을 어느 쪽으로 나눠 봐야 돼?"], ["나누어떨어지면 약수와 배수의 관계다", "18÷3 이 나누어떨어지면 둘은 무슨 관계라고 할 수 있어?"]], "teach": "큰 수를 작은 수로 나눠 보면 돼. 나누어떨어지면 작은 수가 큰 수의 약수이고 큰 수가 작은 수의 배수야. 18÷3=6 으로 나누어떨어지니까 3과 18은 약수와 배수의 관계야.", "again": "24와 5가 약수와 배수의 관계인지 어떻게 알 수 있어? 확인하는 방법을 말해 봐.", "fig": false, "src": "34쪽", "miscon": "나누어떨어지는지 보지 않고 겉모습(짝수·홀수 등)으로 판단함", "record": "약수와 배수의 관계를 '큰 수를 작은 수로 나누어떨어지는지'로 확인하는 방법을 설명하지 못함"}], "e5-1|2. 약수와 배수|03. 공약수와 최대공약수": [{"kind": "뜻", "q": "8과 12의 공약수가 뭔지 말해 봐. 최대공약수는 뭐야?", "ideas": [["두 수의 약수 중에서 공통으로 들어 있는 약수가 공약수다", "8의 약수와 12의 약수를 늘어놓으면 양쪽에 다 있는 수가 뭐야?"], ["공약수 중에서 가장 큰 수가 최대공약수다", "공약수가 여러 개면 그중에 어느 것을 최대공약수라고 불러?"]], "teach": "8의 약수는 1, 2, 4, 8 이고 12의 약수는 1, 2, 3, 4, 6, 12 야. 양쪽에 다 있는 1, 2, 4 가 공약수이고, 그중 가장 큰 4가 최대공약수야.", "again": "10과 15의 공약수는 어떻게 찾아? 최대공약수가 뭔지도 같이 말해 봐.", "fig": false, "src": "36쪽", "miscon": "공약수를 두 수의 곱이나 합으로 생각함", "record": "공약수를 '두 수에 공통인 약수'로 설명하지 못하거나, 최대공약수를 '공약수 중 가장 큰 수'로 말하지 못함"}, {"kind": "성질", "q": "8과 12의 최대공약수는 4야. 그런데 4의 약수 1, 2, 4 가 8과 12의 공약수랑 똑같아. 왜 그럴까?", "ideas": [["공약수는 모두 최대공약수의 약수다", "최대공약수를 나누어떨어지게 하는 수라면, 원래 두 수도 나누어떨어지게 할까?"], ["그래서 공약수를 다 구하려면 최대공약수의 약수를 구하면 된다", "공약수를 빠짐없이 찾고 싶으면 무엇의 약수를 구하면 될까?"]], "teach": "최대공약수의 약수는 모두 공약수야. 그래서 공약수를 하나하나 비교하지 않아도, 최대공약수만 구한 다음 그 약수를 쓰면 공약수를 전부 찾을 수 있어.", "again": "두 수의 최대공약수가 6이래. 이 두 수의 공약수를 전부 말하려면 어떻게 하면 될까?", "fig": false, "src": "36쪽", "miscon": "공약수와 최대공약수의 약수가 같다는 것을 우연으로 봄", "record": "'공약수는 최대공약수의 약수'라는 성질을 설명하지 못하거나, 그것을 공약수를 찾는 방법으로 쓰지 못함"}, {"kind": "함정", "q": "두 수의 공약수 중에서 가장 작은 수는 뭐야? 최소공약수는 왜 따로 안 구할까?", "ideas": [["1은 모든 수의 약수라서 어떤 두 수를 가져와도 1은 반드시 공약수가 된다", "어떤 두 수를 가져와도 1은 둘 다의 약수야?"], ["그래서 공약수 중 가장 작은 수는 언제나 1이고, 따로 구할 필요가 없다", "답이 항상 똑같이 정해져 있으면 굳이 구해야 할까?"]], "teach": "1은 어떤 수든 나누어떨어지게 하니까 모든 수의 약수야. 그래서 두 수를 아무거나 가져와도 공약수 중 가장 작은 수는 항상 1이야. 답이 늘 같으니까 최소공약수는 따로 구하지 않아.", "again": "어떤 두 수를 골라도 공약수에 반드시 들어가는 수가 있어. 그게 뭐고 왜 그런지 말해 봐.", "fig": false, "src": "36쪽", "miscon": "최소공약수도 두 수에 따라 달라진다고 생각함", "record": "공약수 중 가장 작은 수가 항상 1임을 '1은 모든 수의 약수'라는 성질로 설명하지 못함"}], "e5-1|2. 약수와 배수|04. 최대공약수 구하는 방법": [{"kind": "방법", "q": "8과 12를 각각 두 수의 곱으로 나타내서 최대공약수를 구하는 방법을 말해 봐.", "ideas": [["두 수를 각각 두 수의 곱으로 모두 나타낸다", "8과 12를 두 수의 곱으로 쓰면 어떤 식들이 나와?"], ["양쪽에 공통으로 들어 있는 수 중에서 가장 큰 수가 최대공약수다", "8=2×4 와 12=3×4 에 똑같이 들어 있는 수가 뭐야?"]], "teach": "8=1×8=2×4, 12=1×12=2×6=3×4 야. 두 쪽에 공통으로 들어 있는 수는 1, 2, 4 인데 그중 가장 큰 4가 최대공약수야.", "again": "15와 40을 두 수의 곱으로 나타내서 최대공약수를 구하려고 해. 어떤 순서로 하는지 말해 봐.", "fig": false, "src": "38쪽", "miscon": "공통인 수를 고르지 않고 나온 수를 전부 곱함", "record": "곱셈식으로 나타내는 것까지는 하지만, 공통으로 들어 있는 수 중 가장 큰 것을 고른다는 것을 말하지 못함"}, {"kind": "방법", "q": "60과 84처럼 수가 크면 두 수의 곱으로 찾기 어려워. 여러 수의 곱으로 나타내서 최대공약수를 구하는 방법을 말해 봐.", "ideas": [["두 수를 각각 더 쪼갤 수 없을 때까지 여러 수의 곱으로 나타낸다", "60과 84를 두 번 세 번 계속 쪼개면 어떤 모양이 돼?"], ["두 식에 공통으로 들어 있는 곱셈식이 최대공약수다", "60=5×3×2×2 와 84=7×3×2×2 에 똑같이 들어 있는 부분이 뭐야?"]], "teach": "60=5×3×2×2, 84=7×3×2×2 처럼 끝까지 쪼개. 두 식에 똑같이 들어 있는 3×2×2 가 공통 부분이고, 이걸 곱한 12가 60과 84의 최대공약수야.", "again": "36과 48을 여러 수의 곱으로 나타내서 최대공약수를 구하려고 해. 어떤 순서로 하는지 말해 봐.", "fig": false, "src": "38쪽", "miscon": "공통인 곱셈식 전체가 아니라 공통인 수 하나만 최대공약수로 봄", "record": "끝까지 쪼개는 것은 하지만, 공통인 곱셈식 전체를 곱해야 최대공약수가 된다는 것을 설명하지 못함"}, {"kind": "방법", "q": "60과 84를 공약수로 나누어 가면서 최대공약수를 구하는 방법을 순서대로 말해 봐.", "ideas": [["1이 아닌 공약수로 두 수를 나누고 몫을 밑에 쓴다", "두 수를 한꺼번에 나눌 수 있는 수를 무엇이라고 불러?"], ["1 말고는 공약수가 없을 때까지 계속 나눈다", "밑에 쓴 두 몫을 또 나눌 수 있으면 어떻게 해야 돼?"], ["나눈 공약수들을 모두 곱하면 최대공약수다", "왼쪽에 쓴 공약수들을 마지막에 어떻게 해야 돼?"]], "teach": "1이 아닌 공약수로 두 수를 나누고 몫을 밑에 써. 그 몫들도 또 공약수가 있으면 계속 나눠. 더 이상 나눌 수 없으면 왼쪽에 쓴 공약수들을 모두 곱해. 60과 84는 2, 2, 3 으로 나눠져서 최대공약수가 12야.", "again": "48과 72를 공약수로 나누어 최대공약수를 구하려고 해. 어떤 차례로 하는지 순서대로 말해 봐.", "fig": false, "src": "38쪽", "miscon": "최대공약수를 구할 때 왼쪽의 공약수가 아니라 밑에 남은 몫을 곱함", "record": "공약수로 나누는 절차는 알지만, 마지막에 나눈 공약수들만 곱해야 한다는 것을 설명하지 못함"}, {"kind": "함정", "q": "60과 84를 공약수로 나누다가 밑에 5와 7이 남았어. 여기서 나눗셈을 멈춰도 되는 이유를 말해 봐.", "ideas": [["5와 7의 공약수가 1밖에 없기 때문이다", "5와 7을 한꺼번에 나눌 수 있는 수가 1 말고 또 있어?"], ["더 나눌 공약수가 없으면 그때까지 나눈 공약수들의 곱이 최대공약수다", "더 나눌 수 없으면 최대공약수는 어떻게 정해져?"]], "teach": "5와 7을 한꺼번에 나눌 수 있는 수는 1밖에 없어. 1로 나눠 봐야 그대로라서 소용이 없지. 그래서 여기서 멈추고, 그때까지 나눈 공약수 2, 2, 3 을 곱한 12가 최대공약수야.", "again": "공약수로 나누다가 밑에 4와 9가 남았어. 더 나눠야 할까, 멈춰야 할까? 이유와 같이 말해 봐.", "fig": false, "src": "38쪽", "miscon": "1로도 계속 나눠야 한다고 생각해 멈추는 조건을 모름", "record": "'1 말고 공약수가 없을 때 멈춘다'는 조건을 설명하지 못함"}], "e5-1|2. 약수와 배수|05. 공배수와 최소공배수": [{"kind": "뜻", "q": "2와 3의 공배수가 뭔지 말해 봐. 최소공배수는 뭐야?", "ideas": [["두 수의 배수 중에서 공통으로 들어 있는 배수가 공배수다", "2의 배수와 3의 배수를 늘어놓으면 양쪽에 다 나오는 수가 뭐야?"], ["공배수 중에서 가장 작은 수가 최소공배수다", "공배수가 여러 개면 그중에 어느 것을 최소공배수라고 불러?"]], "teach": "2의 배수는 2, 4, 6, 8, 10, 12 … 이고 3의 배수는 3, 6, 9, 12, 15 … 야. 양쪽에 다 나오는 6, 12, 18 … 이 공배수이고, 그중 가장 작은 6이 최소공배수야.", "again": "4와 6의 공배수는 어떻게 찾아? 최소공배수가 뭔지도 같이 말해 봐.", "fig": false, "src": "40쪽", "miscon": "공배수를 두 수의 합이나 차로 생각함", "record": "공배수를 '두 수에 공통인 배수'로 설명하지 못하거나, 최소공배수를 '공배수 중 가장 작은 수'로 말하지 못함"}, {"kind": "성질", "q": "2와 3의 최소공배수는 6인데, 6의 배수 6, 12, 18 … 이 2와 3의 공배수랑 똑같아. 왜 그럴까?", "ideas": [["공배수는 모두 최소공배수의 배수다", "최소공배수를 몇 배 한 수라면 2로도 3으로도 나누어떨어질까?"], ["그래서 공배수를 다 구하려면 최소공배수의 배수를 구하면 된다", "공배수를 빠짐없이 쓰고 싶으면 무엇의 배수를 쓰면 될까?"]], "teach": "최소공배수의 배수는 모두 공배수야. 그래서 두 수의 배수를 각각 길게 늘어놓지 않아도, 최소공배수만 구해서 그걸 1배, 2배, 3배 하면 공배수를 전부 쓸 수 있어.", "again": "두 수의 최소공배수가 8이래. 이 두 수의 공배수를 차례로 말하려면 어떻게 하면 될까?", "fig": false, "src": "40쪽", "miscon": "공배수가 최소공배수의 배수로 모두 만들어진다는 것을 모름", "record": "'공배수는 최소공배수의 배수'라는 성질을 설명하지 못하거나, 그것을 공배수를 찾는 방법으로 쓰지 못함"}, {"kind": "함정", "q": "두 수의 최대공배수는 왜 안 구할까? 이유를 말해 봐.", "ideas": [["공배수는 몇 배든 계속 만들 수 있어서 끝없이 커진다", "공배수를 구하다가 더 이상 만들 수 없는 때가 올까?"], ["끝이 없으니 가장 큰 공배수를 정할 수 없다", "끝없이 커지는 수들 중에서 가장 큰 것을 고를 수 있어?"]], "teach": "공배수는 6, 12, 18, 24 … 처럼 얼마든지 계속 만들 수 있어. 끝이 없으니까 '가장 큰 공배수'라는 건 정할 수가 없어. 그래서 최대공배수는 구하지 않아.", "again": "공약수 중에는 가장 큰 것을 구하는데 공배수 중에는 왜 가장 큰 것을 못 구할까? 이유를 말해 봐.", "fig": false, "src": "40쪽", "miscon": "두 수의 곱을 가장 큰 공배수라고 생각함", "record": "공배수가 끝없이 많아 최대공배수를 정할 수 없다는 것을 설명하지 못함"}], "e5-1|2. 약수와 배수|06. 최소공배수 구하는 방법": [{"kind": "방법", "q": "8과 12를 각각 두 수의 곱으로 나타내서 최소공배수를 구하는 방법을 말해 봐.", "ideas": [["양쪽에 공통으로 들어 있는 가장 큰 수를 찾는다", "8=2×4 와 12=3×4 에 똑같이 들어 있는 수가 뭐야?"], ["그 공통인 수에 남은 수들을 곱한다", "공통인 4를 찾았으면 8 쪽에 남은 2와 12 쪽에 남은 3은 어떻게 해?"]], "teach": "8=2×4, 12=3×4 로 쓰면 공통인 수는 4야. 여기에 남은 2와 3을 곱해서 4×2×3=24 가 8과 12의 최소공배수야.", "again": "6과 15를 두 수의 곱으로 나타내서 최소공배수를 구하려고 해. 어떤 순서로 하는지 말해 봐.", "fig": false, "src": "42쪽", "miscon": "최소공배수를 구할 때 공통인 부분만 쓰고 남은 수를 곱하지 않음(최대공약수와 섞음)", "record": "공통인 수는 찾지만 남은 수들까지 곱해야 최소공배수가 된다는 것을 설명하지 못함"}, {"kind": "방법", "q": "60과 84처럼 수가 크면 여러 수의 곱으로 나타내서 최소공배수를 구해. 어떻게 하는지 말해 봐.", "ideas": [["두 수를 각각 더 쪼갤 수 없을 때까지 여러 수의 곱으로 나타낸다", "60과 84를 계속 쪼개면 어떤 모양이 돼?"], ["공통으로 들어 있는 곱셈식에 남은 수들을 곱한다", "60=5×3×2×2 와 84=7×3×2×2 에서 공통인 3×2×2 를 찾았으면 남은 5와 7은 어떻게 해?"]], "teach": "60=5×3×2×2, 84=7×3×2×2 로 끝까지 쪼개. 공통인 3×2×2 에 남은 5와 7을 곱해서 3×2×2×5×7=420 이 최소공배수야.", "again": "36과 48을 여러 수의 곱으로 나타내서 최소공배수를 구하려고 해. 어떤 순서로 하는지 말해 봐.", "fig": false, "src": "42쪽", "miscon": "공통 부분만 곱해서 최대공약수를 답으로 말함", "record": "공통인 곱셈식은 찾지만 남은 수들까지 곱해야 한다는 것을 빠뜨림"}, {"kind": "방법", "q": "60과 84를 공약수로 나누어서 최소공배수를 구하는 방법을 순서대로 말해 봐.", "ideas": [["1이 아닌 공약수로 두 수를 나누고, 1 말고 공약수가 없을 때까지 계속 나눈다", "밑에 쓴 두 몫을 또 나눌 수 있으면 어떻게 해야 돼?"], ["나눈 공약수와 밑에 남은 두 몫을 모두 곱한다", "왼쪽에 쓴 공약수들만 곱하면 될까, 밑에 남은 수도 곱해야 될까?"]], "teach": "1이 아닌 공약수로 계속 나누는 건 최대공약수 구할 때와 같아. 다만 마지막에 왼쪽의 공약수뿐 아니라 밑에 남은 몫까지 다 곱해. 60과 84는 2, 2, 3 으로 나누고 밑에 5와 7이 남으니까 2×2×3×5×7=420 이야.", "again": "48과 72를 공약수로 나누어 최소공배수를 구하려고 해. 마지막에 무엇들을 곱해야 하는지 말해 봐.", "fig": false, "src": "42쪽", "miscon": "최소공배수를 구하면서 최대공약수처럼 공약수만 곱함", "record": "공약수로 나누는 절차는 알지만, 최소공배수는 밑에 남은 몫까지 곱해야 한다는 것을 설명하지 못함"}, {"kind": "이유", "q": "똑같이 공약수로 나눠도 최대공약수는 왼쪽 공약수만 곱하고 최소공배수는 밑에 남은 몫까지 곱해. 왜 다를까?", "ideas": [["최대공약수는 두 수에 공통으로 들어 있는 부분만 있으면 된다", "두 수를 모두 나누어떨어지게 하려면 공통이 아닌 부분도 필요할까?"], ["최소공배수는 두 수 각각이 통째로 들어가야 해서 남은 몫까지 곱해야 한다", "60의 배수도 되고 84의 배수도 되려면 60 쪽에만 있는 부분도 들어가야 할까?"]], "teach": "최대공약수는 두 수를 모두 나누어떨어지게 해야 하니까 공통인 부분만 있으면 돼. 반대로 최소공배수는 두 수 각각의 배수여야 하니까, 한쪽에만 있는 부분까지 다 들어가야 해. 그래서 남은 몫까지 곱하는 거야.", "again": "최소공배수를 구할 때 밑에 남은 몫을 빼먹고 공약수만 곱하면 왜 안 될까? 이유를 말해 봐.", "fig": false, "src": "42쪽", "miscon": "두 방법의 차이를 외운 절차로만 알고 이유를 설명하지 못함", "record": "최대공약수와 최소공배수에서 곱하는 대상이 다른 이유를 '공통인 부분 / 각각이 통째로 들어가야 함'으로 설명하지 못함"}], "e5-1|3. 규칙과 대응|01. 두 양 사이의 관계": [{"kind": "뜻", "q": "탁자가 1개일 때 의자가 2개, 탁자가 2개일 때 의자가 4개, 탁자가 3개일 때 의자가 6개야. 탁자의 수와 의자의 수 사이에 어떤 관계가 있는지 말해 봐.", "ideas": [["의자의 수는 탁자의 수의 2배다", "탁자가 3개일 때 의자가 6개면, 의자 수는 탁자 수를 몇 배 한 거야?"], ["거꾸로 보면 탁자의 수는 의자의 수의 반이다", "이번엔 의자 쪽에서 탁자 쪽을 보면 어떻게 말할 수 있어?"]], "teach": "탁자 1개에 의자가 2개씩 붙으니까 의자의 수는 탁자의 수의 2배야. 반대로 보면 탁자의 수는 의자의 수의 반이지. 이렇게 한쪽이 정해지면 다른 쪽도 정해지는 두 양의 관계를 대응 관계라고 해.", "again": "자전거가 1대면 바퀴가 2개, 2대면 4개야. 자전거의 수와 바퀴의 수 사이의 관계를 양쪽에서 각각 말해 봐.", "fig": false, "src": "62쪽", "miscon": "몇 배 관계인데 '똑같이 1씩 늘어난다'는 덧셈 관계로 봄", "record": "두 양의 대응 관계를 배 관계로 말하지 못하거나, 한쪽 방향으로만 말하고 거꾸로는 말하지 못함"}, {"kind": "이유", "q": "사각형 1개에 삼각형 2개, 사각형 2개에 삼각형 3개, 사각형 3개에 삼각형 4개로 늘어나. 삼각형의 수는 사각형의 수랑 어떤 관계야? 왜 그렇게 되는지도 말해 봐.", "ideas": [["삼각형의 수는 사각형의 수보다 1 크다", "사각형이 5개면 삼각형은 몇 개가 될 것 같아?"], ["맨 왼쪽 삼각형 1개는 변하지 않고, 사각형 옆에 붙는 삼각형만 늘어나기 때문이다", "늘어날 때 그대로 있는 조각이 하나 있지? 그게 뭐야?"]], "teach": "맨 왼쪽 삼각형 1개는 처음부터 끝까지 그대로 있어. 사각형이 하나 늘 때마다 그 옆에 삼각형이 하나씩 더 붙지. 그래서 삼각형의 수는 언제나 사각형의 수보다 1 커.", "again": "성냥개비로 삼각형을 이어 붙이는데, 처음 삼각형은 3개가 필요하고 하나 늘 때마다 2개씩 더 필요해. 변하지 않는 부분이 뭐고 변하는 부분이 뭔지 말해 봐.", "fig": false, "src": "62쪽", "miscon": "변하지 않는 부분을 빼고 세어서, 늘어나는 양을 잘못 셈", "record": "배열에서 변하지 않는 부분과 변하는 부분을 갈라 보지 못해 대응 관계를 설명하지 못함"}, {"kind": "적용", "q": "탁자가 10개면 의자가 몇 개인지, 그림을 하나하나 그려 보지 않고도 알 수 있어. 어떻게 알 수 있는지 말해 봐.", "ideas": [["먼저 탁자 수와 의자 수 사이의 규칙을 찾는다", "그림을 안 그리고 알려면 무엇부터 찾아야 돼?"], ["규칙을 찾아 두면 그리지 않고도 큰 수까지 구할 수 있다", "규칙을 알면 탁자가 100개일 때도 구할 수 있어?"]], "teach": "먼저 규칙을 찾아야 해. 의자의 수는 탁자의 수의 2배라는 걸 알면 탁자가 10개일 때 의자는 20개라는 걸 그림 없이 알 수 있어. 규칙을 찾아 두면 수가 아무리 커져도 쓸 수 있는 게 좋은 점이야.", "again": "자전거가 20대일 때 바퀴가 몇 개인지 그림 없이 알려면 무엇부터 해야 할까? 말해 봐.", "fig": false, "src": "62쪽", "miscon": "규칙을 찾지 않고 매번 세어서만 답을 구하려고 함", "record": "대응 관계의 규칙을 찾아 두면 세지 않고도 구할 수 있다는 점을 설명하지 못함"}], "e5-1|3. 규칙과 대응|02. 대응 관계를 식으로 나타내기": [{"kind": "방법", "q": "자동차가 1대면 바퀴가 4개, 2대면 8개, 3대면 12개야. 이 대응 관계를 곱셈식이랑 나눗셈식으로 각각 어떻게 나타내는지 말해 봐.", "ideas": [["자동차의 수에 4를 곱하면 바퀴의 수가 되므로 (자동차의 수)×4=(바퀴의 수) 로 쓴다", "자동차 수에 얼마를 곱하면 바퀴 수가 돼?"], ["바퀴의 수를 4로 나누면 자동차의 수가 되므로 (바퀴의 수)÷4=(자동차의 수) 로 쓴다", "이번엔 바퀴 수에서 자동차 수를 구하려면 어떤 계산을 해?"]], "teach": "자동차 1대에 바퀴가 4개씩이니까 자동차의 수에 4를 곱하면 바퀴의 수야. 식으로는 (자동차의 수)×4=(바퀴의 수). 거꾸로 바퀴의 수를 4로 나누면 자동차의 수라서 (바퀴의 수)÷4=(자동차의 수) 라고도 쓸 수 있어.", "again": "한 상자에 사탕이 6개씩 들어 있어. 상자의 수와 사탕의 수 사이의 관계를 곱셈식과 나눗셈식으로 각각 말해 봐.", "fig": false, "src": "64쪽", "miscon": "배 관계를 덧셈 관계로 잘못 옮김", "record": "대응 관계를 곱셈식이나 나눗셈식으로 나타내지 못하거나, 한쪽 식만 말하고 다른 쪽을 빠뜨림"}, {"kind": "방법", "q": "'자동차의 수'처럼 말이 길면 식이 복잡해져. 더 간단하게 쓰는 방법을 말해 봐.", "ideas": [["각 양을 ○, □, △, ☆ 같은 기호로 정한다", "긴 말 대신에 무엇을 써서 나타낼 수 있을까?"], ["정한 기호를 넣어 △×4=● 처럼 짧게 쓴다", "자동차를 △, 바퀴를 ● 로 정했으면 식이 어떤 모양이 돼?"]], "teach": "각 양을 ○, □, △, ☆ 같은 기호로 정하면 식이 짧아져. 자동차의 수를 △, 바퀴의 수를 ● 로 정하면 △×4=● 라고 쓸 수 있어. 어떤 기호를 쓰는지는 내가 정하면 돼.", "again": "상자의 수를 □, 사탕의 수를 ☆ 로 정했어. 한 상자에 사탕이 6개씩 들어 있을 때 식을 어떻게 쓰면 될까?", "fig": false, "src": "64쪽", "miscon": "기호가 미리 정해져 있다고 생각해 스스로 정하지 못함", "record": "양을 기호로 정해 식을 간단히 나타내는 방법을 설명하지 못함"}, {"kind": "방법", "q": "표에 ○가 2, 3, 4 이고 △가 4, 5, 6 이야. 두 수 사이의 규칙을 어떻게 찾는지 말해 봐.", "ideas": [["두 수의 차가 늘 같은지 확인한다", "4−2, 5−3, 6−4 를 해 보면 뭐가 보여?"], ["차가 일정하지 않으면 큰 수를 작은 수로 나눈 몫이 늘 같은지 확인한다", "차로 규칙이 안 보이면 그 다음엔 뭘 해 봐야 돼?"]], "teach": "먼저 두 수의 차를 봐. 4−2, 5−3, 6−4 가 모두 2라서 △−○=2, 곧 ○+2=△ 야. 차가 일정하지 않으면 큰 수를 작은 수로 나눠 봐. 몫이 늘 같으면 배 관계인 거야.", "again": "표에 ○가 2, 3, 4 이고 △가 4, 6, 8 이야. 어떤 규칙인지 어떻게 알아내는지 말해 봐.", "fig": false, "src": "64쪽", "miscon": "차나 몫을 따져 보지 않고 아무 계산이나 해서 규칙을 찾으려 함", "record": "대응 관계의 규칙을 찾을 때 차와 몫을 차례로 확인하는 방법을 설명하지 못함"}], "e5-1|3. 규칙과 대응|03. 생활 속에서 대응 관계 찾기": [{"kind": "적용", "q": "라면 한 상자에 라면이 30개씩 들어 있어. 상자의 수와 라면의 수 사이의 대응 관계를 말로 말해 봐.", "ideas": [["상자의 수에 30을 곱하면 라면의 수가 된다", "상자가 2개면 라면은 몇 개가 돼? 그럼 무슨 계산을 한 거야?"], ["거꾸로 라면의 수를 30으로 나누면 상자의 수가 된다", "이번엔 라면 개수를 알 때 상자 수를 어떻게 구해?"]], "teach": "한 상자에 30개씩이니까 상자의 수에 30을 곱하면 라면의 수가 돼. 거꾸로 라면의 수를 30으로 나누면 상자의 수가 나오지. 생활 속 두 양도 이렇게 곱셈이나 나눗셈으로 이어져 있어.", "again": "과자 한 봉지가 150킬로칼로리야. 과자의 수와 킬로칼로리 사이의 대응 관계를 말로 말해 봐.", "fig": false, "src": "66쪽", "miscon": "생활 속 상황에서 '한 묶음에 몇 개'라는 배 관계를 못 읽어 냄", "record": "생활 속 두 양의 대응 관계를 곱셈·나눗셈으로 말하지 못하거나 한쪽 방향만 말함"}, {"kind": "적용", "q": "연필 한 상자에 연필이 12자루씩 들어 있어. 연필의 수를 ★, 상자의 수를 ▲ 라고 할 때 대응 관계를 식으로 어떻게 써?", "ideas": [["연필의 수를 12로 나누면 상자의 수가 된다", "연필 24자루면 상자가 몇 개야? 무슨 계산을 한 거야?"], ["★÷12=▲ 라고 쓴다", "연필을 ★, 상자를 ▲ 로 정했으면 그 계산이 어떤 식이 돼?"]], "teach": "연필 12자루가 한 상자니까 연필의 수를 12로 나누면 상자의 수가 나와. 연필을 ★, 상자를 ▲ 로 정했으니 ★÷12=▲ 라고 쓰면 돼.", "again": "꽃 한 송이에 꽃잎이 5장씩이야. 꽃잎의 수를 ◆, 꽃의 수를 ■ 라고 할 때 식을 어떻게 쓸까?", "fig": false, "src": "66쪽", "miscon": "곱셈과 나눗셈의 방향을 거꾸로 써서, 작은 쪽에서 큰 쪽을 구하는 식으로 만듦", "record": "대응 관계를 기호를 쓴 식으로 옮길 때 곱셈·나눗셈 방향을 정하지 못함"}, {"kind": "함정", "q": "같은 대응 관계를 두고 한 친구는 ●+4=■ 라고 쓰고 다른 친구는 ■−4=● 라고 썼어. 둘 다 맞을까? 왜 그런지 말해 봐.", "ideas": [["둘 다 맞다. 같은 관계를 어느 쪽에서 보느냐만 다르기 때문이다", "두 식이 서로 다른 관계를 말하고 있어, 아니면 같은 관계를 말하고 있어?"], ["● 를 기준으로 하면 ●+4=■, ■ 를 기준으로 하면 ■−4=● 가 된다", "● 에서 ■ 를 구할 때랑 ■ 에서 ● 를 구할 때 계산이 어떻게 달라져?"]], "teach": "같은 대응 관계라도 어느 쪽을 기준으로 보느냐에 따라 식 모양이 달라져. ● 에서 ■ 를 구하면 ●+4=■, ■ 에서 ● 를 구하면 ■−4=● 야. 둘은 같은 관계를 다르게 쓴 거라 둘 다 맞아.", "again": "상자의 수와 라면의 수 사이의 관계를 한 친구는 곱셈식으로, 다른 친구는 나눗셈식으로 썼어. 둘 다 맞는지 이유와 같이 말해 봐.", "fig": false, "src": "66쪽", "miscon": "대응 관계를 나타내는 식이 한 가지뿐이라고 생각함", "record": "같은 대응 관계를 기준에 따라 여러 식으로 쓸 수 있다는 것을 설명하지 못함"}], "e5-1|4. 약분과 통분|01. 크기가 같은 분수": [{"kind": "이유", "q": "1/3 이랑 2/6 은 분모가 다른데 크기가 같아. 어떻게 크기가 같을 수 있는지 말해 봐.", "ideas": [["전체를 나눈 칸 수가 2배가 되면 가져오는 칸 수도 2배가 되어 차지하는 양이 그대로다", "1/3 에서 2/6 이 될 때 나눈 칸 수만 늘었어, 가져온 칸 수도 같이 늘었어?"], ["수직선에 나타내 보면 두 분수가 같은 자리에 있다", "두 분수를 수직선에 찍어 보면 자리가 어떻게 돼?"]], "teach": "1/3 은 전체를 3칸으로 나눈 것 중 1칸이고, 2/6 은 6칸으로 나눈 것 중 2칸이야. 칸을 2배로 잘게 나눈 대신 가져오는 칸도 2배가 되어서 차지하는 양은 그대로야. 수직선에 찍어 보면 같은 자리에 있어.", "again": "2/5 랑 4/10 은 왜 크기가 같을까? 이유를 말해 봐.", "fig": false, "src": "84쪽", "miscon": "분모만 보고 분수의 크기를 판단함(분자가 함께 커진 것을 못 봄)", "record": "분모와 분자가 함께 몇 배가 되면 크기가 그대로라는 것을 설명하지 못함"}, {"kind": "방법", "q": "크기가 같은 분수를 만드는 방법이 두 가지 있어. 각각 말해 봐.", "ideas": [["분모와 분자에 0이 아닌 같은 수를 곱한다", "1/3 에 무엇을 해서 2/6 을 만들 수 있어?"], ["분모와 분자를 0이 아닌 같은 수로 나눈다", "이번엔 반대로 4/12 에서 1/3 을 만들려면 어떻게 해?"]], "teach": "분모와 분자에 0이 아닌 같은 수를 곱하면 크기가 같은 분수가 돼. 반대로 분모와 분자를 0이 아닌 같은 수로 나눠도 크기가 같아. 나눌 때 쓰는 수는 분모와 분자의 공약수여야 해.", "again": "3/5 와 크기가 같은 분수를 만들려면 무엇을 어떻게 하면 돼? 두 가지 방법을 말해 봐.", "fig": false, "src": "84쪽", "miscon": "분모나 분자 한쪽에만 곱하거나 나눔", "record": "크기가 같은 분수를 만드는 두 방법(같은 수를 곱하기·나누기)을 말하지 못하거나 한쪽만 말함"}, {"kind": "함정", "q": "분모와 분자에 같은 수를 '더하면' 크기가 같은 분수가 될까? 왜 그런지 말해 봐.", "ideas": [["더해서는 크기가 같은 분수가 되지 않는다. 곱하거나 나눌 때만 크기가 그대로다", "1/3 의 분모와 분자에 1씩 더하면 2/4 가 되는데, 1/3 이랑 2/4 가 같아?"], ["같은 수를 더하면 분자가 분모의 몇 분의 몇인지가 달라져 버린다", "1/3 은 3칸 중 1칸인데 2/4 는 4칸 중 2칸이야. 차지하는 양이 그대로야?"]], "teach": "안 돼. 1/3 의 분모와 분자에 1을 더하면 2/4 인데, 1/3 은 3칸 중 1칸이고 2/4 는 4칸 중 2칸이라 차지하는 양이 달라. 같은 수를 곱하거나 나눌 때만 크기가 그대로야.", "again": "2/5 의 분모와 분자에 2씩 더해서 4/7 을 만들었어. 두 분수의 크기가 같을까? 이유와 같이 말해 봐.", "fig": false, "src": "84쪽", "miscon": "곱셈·나눗셈에서 되는 것이 덧셈에서도 된다고 생각함", "record": "분모와 분자에 같은 수를 더하면 크기가 달라진다는 것을 예로 설명하지 못함"}], "e5-1|4. 약분과 통분|02. 약분": [{"kind": "뜻", "q": "분수를 약분한다는 게 뭔지 말해 봐. 나눌 때 1은 왜 안 써?", "ideas": [["분모와 분자를 공약수로 나누어 간단하게 만드는 것이 약분이다", "분모와 분자를 무엇으로 나누어야 크기가 그대로 있어?"], ["1로 나누면 자기 자신 그대로라서 간단해지지 않기 때문이다", "8/20 을 1로 나누면 뭐가 돼?"]], "teach": "약분은 분모와 분자를 공약수로 나누어 더 간단한 분수로 만드는 거야. 다만 1로 나누면 그대로라서 간단해지지 않으니까, 1을 뺀 공약수로 나눠.", "again": "12/18 을 약분하려고 해. 약분이 무엇이고 어떤 수로 나눠야 하는지 말해 봐.", "fig": false, "src": "86쪽", "miscon": "약분을 뺄셈으로 생각함", "record": "약분을 '공약수로 나누어 간단히 하는 것'으로 설명하지 못함"}, {"kind": "방법", "q": "8/20 을 약분하는 차례를 말해 봐.", "ideas": [["분모와 분자의 공약수를 먼저 구한다", "8과 20을 함께 나눌 수 있는 수를 어떻게 찾아?"], ["1을 뺀 공약수로 분모와 분자를 나눈다", "공약수 1, 2, 4 를 찾았으면 그 다음엔 뭘 해?"]], "teach": "먼저 8과 20의 공약수를 구해. 1, 2, 4 야. 1을 빼고 2로 나누면 4/10, 4로 나누면 2/5 가 돼. 어느 공약수로 나누든 크기는 그대로야.", "again": "9/12 를 약분하려면 어떤 차례로 해야 하는지 말해 봐.", "fig": false, "src": "86쪽", "miscon": "분모와 분자 중 한쪽만 나눔", "record": "약분하는 차례(공약수 구하기 → 분모·분자를 함께 나누기)를 설명하지 못함"}, {"kind": "뜻", "q": "기약분수가 뭐야? 한 번에 기약분수로 만드는 방법도 말해 봐.", "ideas": [["분모와 분자의 공약수가 1뿐인 분수가 기약분수다", "더 이상 약분이 안 되는 분수는 공약수가 무엇만 남아 있을까?"], ["분모와 분자를 최대공약수로 나누면 한 번에 기약분수가 된다", "여러 번 나누지 않고 한 번에 끝내려면 무엇으로 나눠야 돼?"]], "teach": "기약분수는 분모와 분자의 공약수가 1뿐이라 더 이상 약분할 수 없는 분수야. 8과 20의 최대공약수인 4로 한 번에 나누면 2/5 라는 기약분수가 바로 나와.", "again": "18/24 를 한 번에 기약분수로 만들려면 무엇으로 나눠야 할까? 기약분수가 뭔지도 말해 봐.", "fig": false, "src": "86쪽", "miscon": "기약분수를 '분모가 작은 분수'로 잘못 알고 있음", "record": "기약분수를 '공약수가 1뿐인 분수'로 설명하지 못하거나, 최대공약수로 한 번에 만드는 방법을 모름"}, {"kind": "함정", "q": "8/20 을 2로 나눠서 4/10 을 만들었어. 여기서 약분을 끝내도 될까? 왜 그런지 말해 봐.", "ideas": [["끝내면 안 된다. 4와 10에 아직 공약수 2가 남아 있다", "4와 10을 함께 나눌 수 있는 수가 1 말고 또 있어?"], ["더 이상 나누어지지 않을 때까지 나눠야 기약분수가 된다", "약분은 언제까지 계속해야 돼?"]], "teach": "4와 10은 아직 2로 함께 나눌 수 있어. 그래서 4/10 은 기약분수가 아니야. 한 번 더 나눠서 2/5 가 되어야 끝이야. 약분은 더 이상 나누어지지 않을 때까지 하는 거야.", "again": "12/18 을 2로 나눠서 6/9 를 만들었어. 여기서 멈춰도 될까? 이유와 같이 말해 봐.", "fig": false, "src": "86쪽", "miscon": "한 번만 약분하면 끝이라고 생각해 기약분수인지 확인하지 않음", "record": "약분을 끝내는 조건(더 이상 공약수가 없을 때)을 설명하지 못함"}], "e5-1|4. 약분과 통분|03. 통분": [{"kind": "뜻", "q": "통분한다는 게 뭐야? 공통분모는 뭐고?", "ideas": [["분모가 다른 분수들의 분모를 같게 만드는 것이 통분이다", "3/4 과 1/6 을 견주기 어려운 건 무엇이 다르기 때문이야?"], ["통분해서 같아진 분모를 공통분모라고 한다", "통분하고 나면 두 분수의 분모가 어떻게 돼? 그걸 뭐라고 불러?"]], "teach": "분모가 다르면 크기를 견주기 어려워. 그래서 분모를 같게 만드는데 이걸 통분한다고 해. 통분해서 같아진 그 분모를 공통분모라고 불러.", "again": "2/3 과 3/5 를 견주기 쉽게 고치려고 해. 무엇을 하는 거고 뭐라고 부르는지 말해 봐.", "fig": false, "src": "88쪽", "miscon": "통분을 분자를 맞추는 것으로 잘못 알고 있음", "record": "통분을 '분모를 같게 하는 것'으로 설명하지 못하거나 공통분모라는 말을 쓰지 못함"}, {"kind": "방법", "q": "3/4 과 1/6 을 통분할 때 두 분모의 곱을 공통분모로 삼는 방법을 말해 봐.", "ideas": [["두 분모를 곱한 수를 공통분모로 삼는다", "4와 6으로 공통분모를 만들려면 가장 쉽게 어떤 수를 쓸 수 있어?"], ["각 분수의 분모와 분자에 상대편 분모를 곱한다", "3/4 을 분모가 24인 분수로 만들려면 분모와 분자에 무엇을 곱해?"]], "teach": "4와 6을 곱한 24를 공통분모로 삼으면 돼. 3/4 은 분모와 분자에 6을 곱해서 18/24, 1/6 은 4를 곱해서 4/24 가 돼. 분모가 작을 때 쓰기 편한 방법이야.", "again": "2/3 과 1/5 을 두 분모의 곱으로 통분하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "88쪽", "miscon": "분모만 바꾸고 분자를 같이 바꾸지 않아 크기가 달라짐", "record": "두 분모의 곱으로 통분할 때 분자에도 상대편 분모를 곱해야 한다는 것을 빠뜨림"}, {"kind": "방법", "q": "3/4 과 1/6 을 두 분모의 최소공배수로 통분하는 방법을 말해 봐. 이 방법은 언제 더 편해?", "ideas": [["두 분모의 최소공배수를 공통분모로 삼는다", "4와 6을 둘 다 나누어떨어지게 하는 수 중에 가장 작은 게 뭐야?"], ["분모가 커서 그냥 곱하면 수가 너무 커질 때 편하다", "분모가 12와 18이면 곱했을 때 수가 어떻게 돼?"]], "teach": "4와 6의 최소공배수는 12야. 3/4 은 9/12, 1/6 은 2/12 가 돼. 두 분모를 그냥 곱하면 24라서 수가 커지는데, 최소공배수를 쓰면 수가 작아져서 계산이 편해. 분모가 클수록 이 방법이 좋아.", "again": "5/8 과 3/12 를 최소공배수로 통분하려고 해. 공통분모를 어떻게 정하는지 말해 봐.", "fig": false, "src": "88쪽", "miscon": "통분에 최소공배수가 아니라 최대공약수를 씀", "record": "최소공배수를 공통분모로 삼는 방법을 말하지 못하거나, 언제 편리한지 설명하지 못함"}, {"kind": "성질", "q": "공통분모가 될 수 있는 수는 아무 수나 되는 게 아니야. 어떤 수들이 공통분모가 될 수 있는지 말해 봐.", "ideas": [["두 분모의 공배수가 공통분모가 될 수 있다", "공통분모는 두 분모로 각각 나누어떨어져야 할까?"], ["공배수 중에서 가장 작은 최소공배수를 쓰면 수가 가장 작아진다", "공배수가 여러 개면 그중 어느 것을 쓰는 게 좋아?"]], "teach": "공통분모는 두 분모 각각의 배수여야 해. 그러니까 두 분모의 공배수만 공통분모가 될 수 있어. 4와 6이면 12, 24, 36 … 이 다 되는데, 그중 가장 작은 12를 쓰면 수가 제일 작아서 편해.", "again": "분모가 6과 9인 두 분수를 통분하려고 해. 공통분모가 될 수 있는 수가 무엇인지, 어느 것을 쓰면 좋은지 말해 봐.", "fig": false, "src": "88쪽", "miscon": "공통분모가 두 분모의 공배수여야 한다는 조건을 모름", "record": "공통분모가 될 수 있는 수를 '두 분모의 공배수'로 설명하지 못함"}], "e5-1|4. 약분과 통분|04. 분수의 크기 비교": [{"kind": "방법", "q": "1/2 과 3/5 처럼 분모가 다른 두 분수의 크기는 어떻게 비교해?", "ideas": [["통분하거나 약분해서 분모를 같게 만든다", "분모가 다르면 왜 바로 견주기 어려울까?"], ["분모가 같아지면 분자가 큰 쪽이 더 큰 분수다", "분모가 같아진 다음에는 무엇을 보고 정해?"]], "teach": "분모가 다르면 한 칸의 크기가 서로 달라서 바로 견줄 수 없어. 통분해서 분모를 같게 만들면 한 칸 크기가 같아지니까, 그때는 분자가 큰 쪽이 더 큰 분수야.", "again": "2/3 과 3/4 의 크기를 비교하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "90쪽", "miscon": "통분하지 않고 분모나 분자만 보고 크기를 판단함", "record": "분모를 같게 만든 뒤 분자를 비교한다는 절차를 설명하지 못함"}, {"kind": "방법", "q": "분모가 다른 세 분수의 크기는 어떻게 비교해? 두 가지 방법을 말해 봐.", "ideas": [["두 분수씩 짝지어 차례로 통분해서 비교한다", "세 개를 한꺼번에 견주기 어려우면 몇 개씩 묶어서 보면 될까?"], ["세 분수를 한꺼번에 통분해서 비교해도 된다", "세 분모의 공배수를 찾으면 한 번에 견줄 수 있을까?"]], "teach": "두 분수씩 짝지어 통분해서 차례로 견주면 돼. 아니면 세 분모의 공배수를 공통분모로 삼아 세 분수를 한꺼번에 통분해도 좋아. 결과는 같아.", "again": "1/2, 2/3, 3/4 의 크기를 비교하려고 해. 어떤 방법으로 할 수 있는지 말해 봐.", "fig": false, "src": "90쪽", "miscon": "통분하지 않고 분자만 보고 세 분수를 늘어놓음", "record": "세 분수를 비교하는 방법(짝지어 통분 / 한꺼번에 통분)을 설명하지 못함"}, {"kind": "성질", "q": "2/3, 2/4, 2/5 처럼 분자가 같은 분수들은 어느 것이 가장 커? 왜 그런지도 말해 봐.", "ideas": [["분모가 작을수록 큰 수다", "2/3 과 2/5 중에 어느 쪽이 더 커?"], ["전체를 적게 나눌수록 한 조각이 커지기 때문이다", "똑같은 피자를 3조각으로 나눌 때와 5조각으로 나눌 때, 한 조각이 어느 쪽이 커?"]], "teach": "분자가 같으면 가져오는 조각 수는 같아. 그런데 전체를 적게 나눌수록 한 조각이 커지니까, 분모가 작을수록 큰 분수야. 그래서 2/3 이 가장 크고 2/5 가 가장 작아.", "again": "3/7 과 3/10 중에 어느 것이 더 클까? 왜 그런지 이유와 같이 말해 봐.", "fig": false, "src": "90쪽", "miscon": "분모가 크면 분수도 크다고 생각함", "record": "분자가 같을 때 분모가 작을수록 크다는 것을, 한 조각의 크기로 설명하지 못함"}], "e5-1|4. 약분과 통분|05. 분수와 소수의 크기 비교": [{"kind": "방법", "q": "3/4 이랑 0.35 의 크기를 비교하려고 해. 분수를 소수로 바꿔서 비교하는 방법을 말해 봐.", "ideas": [["분모가 10, 100, 1000 이 되도록 크기가 같은 분수로 고친다", "3/4 의 분모를 100으로 만들려면 분모와 분자에 무엇을 곱해?"], ["분모가 10, 100 인 분수는 바로 소수로 바꿔서 비교한다", "75/100 은 소수로 어떻게 써?"]], "teach": "3/4 의 분모와 분자에 25를 곱하면 75/100 이야. 분모가 100인 분수는 0.75 라고 바로 쓸 수 있어. 0.75 와 0.35 를 견주면 3/4 이 더 크지.", "again": "1/2 과 0.4 의 크기를 비교하려고 해. 분수를 소수로 바꾸는 방법으로 어떻게 하는지 말해 봐.", "fig": false, "src": "92쪽", "miscon": "분수를 분자와 분모를 그대로 이어 붙인 소수로 잘못 읽음", "record": "분모를 10·100으로 고쳐 소수로 바꾸는 방법을 설명하지 못함"}, {"kind": "방법", "q": "0.4 랑 4/7 처럼 소수로 딱 떨어지지 않는 분수는 어떻게 비교해?", "ideas": [["소수를 분수로 바꾼다", "0.4 를 분수로 쓰면 어떤 분수가 돼?"], ["두 분수를 통분해서 분자를 비교한다", "분수 두 개가 되면 그 다음엔 뭘 해?"]], "teach": "4/7 은 분모를 10이나 100으로 만들 수 없어서 소수로 딱 떨어지지 않아. 이럴 땐 반대로 0.4 를 4/10 으로 바꾸고, 4/10 과 4/7 을 통분해서 견주면 돼.", "again": "0.6 이랑 5/9 의 크기를 비교하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "92쪽", "miscon": "소수로 바꿀 수 없으면 비교 자체가 안 된다고 생각함", "record": "소수를 분수로 바꿔 통분하는 방법을 설명하지 못함"}, {"kind": "전략", "q": "분수와 소수를 비교할 때 어느 쪽으로 바꿀지 어떻게 정해? 정하는 기준을 말해 봐.", "ideas": [["분모를 10, 100, 1000 으로 만들 수 있으면 분수를 소수로 바꿔 비교한다", "3/4 은 분모를 100으로 만들 수 있어? 그럼 어느 쪽으로 바꾸는 게 편해?"], ["그렇게 만들 수 없으면 소수를 분수로 바꿔 통분해서 비교한다", "4/7 처럼 분모를 100으로 못 만들면 어느 쪽으로 바꿔야 돼?"]], "teach": "분모를 10, 100, 1000 으로 만들 수 있는 분수면 소수로 바꿔 견주는 게 빨라. 4/7 처럼 그게 안 되는 분수면 반대로 소수를 분수로 바꿔서 통분해. 어느 쪽이 쉬운지 먼저 살펴보고 고르면 돼.", "again": "1/8 과 0.2 를 비교할 때 어느 쪽으로 바꾸는 게 좋을까? 그렇게 정한 까닭도 말해 봐.", "fig": false, "src": "92쪽", "miscon": "모든 분수가 소수로 딱 떨어진다고 생각해 한 가지 방법만 씀", "record": "분모를 10·100으로 만들 수 있는지에 따라 방법을 고른다는 기준을 설명하지 못함"}], "e5-1|5. 분수의 덧셈과 뺄셈|01. 분수의 덧셈 (1), (2)": [{"kind": "이유", "q": "1/4 + 2/6 처럼 분모가 다른 두 분수는 왜 바로 더할 수 없어? 먼저 무엇을 해야 하는지도 말해 봐.", "ideas": [["분모가 다르면 한 칸의 크기가 서로 달라서 그냥 더할 수 없다", "4칸으로 나눈 것 중 1칸이랑 6칸으로 나눈 것 중 1칸은 크기가 같아?"], ["먼저 통분해서 분모를 같게 만들어야 한다", "칸의 크기를 같게 만들려면 무엇을 해야 돼?"]], "teach": "1/4 은 전체를 4칸으로 나눈 것 중 1칸이고 2/6 은 6칸으로 나눈 것 중 2칸이야. 한 칸의 크기가 달라서 그냥 더할 수 없어. 통분해서 분모를 같게 만들면 칸 크기가 같아져서 더할 수 있어.", "again": "1/3 + 1/5 를 바로 더할 수 없는 까닭이 뭐야? 먼저 무엇을 해야 하는지도 말해 봐.", "fig": false, "src": "112쪽", "miscon": "분모끼리 분자끼리 각각 더해도 된다고 생각함", "record": "분모가 다르면 한 칸의 크기가 달라 바로 더할 수 없다는 것을 설명하지 못함"}, {"kind": "방법", "q": "분모가 다른 두 진분수를 더하는 차례를 말해 봐. 공통분모는 어떻게 정할 수 있어?", "ideas": [["두 분모의 곱이나 최소공배수를 공통분모로 삼아 통분한다", "공통분모로 쓸 수 있는 수를 어떻게 구할 수 있어?"], ["분모가 같아지면 분자끼리 더한다", "통분을 마치고 나면 무엇끼리 더해?"]], "teach": "먼저 통분해. 공통분모는 두 분모를 곱한 수로 해도 되고 두 분모의 최소공배수로 해도 돼. 분모가 같아지면 분모는 그대로 두고 분자끼리만 더하면 돼.", "again": "1/6 + 7/8 을 계산하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "112쪽", "miscon": "통분한 뒤 분모까지 더해 버림", "record": "통분 후 분자끼리만 더한다는 절차를 설명하지 못함"}, {"kind": "함정", "q": "분수를 더했더니 답이 14/24 가 나왔어. 이대로 두면 될까? 답을 어떻게 마무리해야 하는지 말해 봐.", "ideas": [["약분이 되면 기약분수로 고친다", "14와 24를 함께 나눌 수 있는 수가 1 말고 또 있어?"], ["분자가 분모보다 큰 가분수가 되면 대분수로 바꾼다", "더한 답이 57/54 처럼 나오면 어떻게 써야 돼?"]], "teach": "14/24 는 2로 약분해서 7/12 로 써야 해. 또 57/54 처럼 분자가 분모보다 크면 1과 3/54 같은 대분수로 바꾸고, 그 분수 부분도 약분해서 1과 1/18 로 마무리해.", "again": "분수를 더한 답이 10/8 로 나왔어. 어떻게 마무리해야 할지 말해 봐.", "fig": false, "src": "112쪽", "miscon": "계산만 끝내고 약분·대분수 고치기를 하지 않음", "record": "답을 기약분수·대분수로 마무리해야 한다는 것을 말하지 못하거나 한쪽만 말함"}, {"kind": "전략", "q": "공통분모를 두 분모의 곱으로 할 수도 있고 최소공배수로 할 수도 있어. 각각 어떤 점이 좋은지 말해 봐.", "ideas": [["두 분모를 곱하면 공통분모를 바로 구할 수 있어 쉽다", "4와 6의 공통분모를 가장 빨리 떠올리려면 어떻게 하면 돼?"], ["최소공배수로 하면 수가 작아서 마지막에 약분할 일이 적다", "4와 6을 곱한 24로 할 때랑 최소공배수 12로 할 때, 어느 쪽 수가 더 작아?"]], "teach": "두 분모를 곱하면 공통분모를 구하기가 쉬워. 대신 수가 커져서 마지막에 약분할 일이 많아지지. 최소공배수를 쓰면 수가 작아서 약분할 일이 적어. 분모가 클수록 최소공배수 쪽이 편해.", "again": "분모가 8과 12인 두 분수를 더하려고 해. 공통분모를 96으로 할 때와 24로 할 때 무엇이 다른지 말해 봐.", "fig": false, "src": "112쪽", "miscon": "공통분모를 무엇으로 정하느냐에 따라 답 자체가 달라진다고 생각함", "record": "두 공통분모 정하는 방법의 장단점을 설명하지 못함"}], "e5-1|5. 분수의 덧셈과 뺄셈|02. 분수의 덧셈 (3)": [{"kind": "방법", "q": "1과 1/2 더하기 1과 7/10 처럼 대분수끼리 더하는 방법 한 가지를 말해 봐.", "ideas": [["자연수는 자연수끼리, 분수는 분수끼리 더한다", "대분수는 자연수 부분과 분수 부분으로 되어 있지? 각각 어떻게 해?"], ["분수 부분은 분모가 다르면 먼저 통분해서 더한다", "1/2 과 7/10 은 분모가 다른데 바로 더할 수 있어?"]], "teach": "대분수는 자연수 부분과 분수 부분으로 나눠서, 자연수는 자연수끼리 분수는 분수끼리 더하면 편해. 분수 부분은 분모가 다르면 먼저 통분한 다음에 더해야 해.", "again": "2와 1/3 더하기 1과 1/4 을 자연수끼리 분수끼리 계산하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "114쪽", "miscon": "분수 부분을 통분하지 않고 바로 분자끼리 더함", "record": "대분수 덧셈에서 자연수·분수를 나눠 계산하는 방법을 말하지 못하거나 통분을 빠뜨림"}, {"kind": "방법", "q": "대분수를 가분수로 바꿔서 더하는 방법도 있어. 어떤 차례로 하는지 말해 봐.", "ideas": [["두 대분수를 먼저 가분수로 바꾼다", "자연수 부분과 분수 부분을 따로 떼지 않으려면 먼저 무엇으로 고쳐?"], ["통분해서 분자끼리 더한 뒤 다시 대분수로 바꾼다", "가분수끼리 더하고 나면 답을 어떤 모양으로 써?"]], "teach": "대분수를 먼저 가분수로 바꾸면 자연수와 분수를 따로 떼어 계산하지 않아도 돼. 가분수끼리 통분해서 분자끼리 더하고, 나온 가분수를 다시 대분수로 바꾸면 끝이야.", "again": "1과 1/2 더하기 1과 7/10 을 가분수로 바꿔서 계산하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "114쪽", "miscon": "가분수로 바꾸면 통분이 필요 없다고 생각함", "record": "가분수로 바꿔 더하는 차례를 설명하지 못하거나 통분·되돌리기 단계를 빠뜨림"}, {"kind": "방법", "q": "1과 1/2 을 가분수로 바꾸는 방법을 말해 봐.", "ideas": [["자연수에 분모를 곱하고 분자를 더해서 새 분자로 쓴다", "자연수 1은 분모가 2일 때 몇 분의 몇으로 바꿀 수 있어?"], ["분모는 그대로 둔다", "가분수로 바꾸면 분모도 바뀌어?"]], "teach": "자연수 1은 분모가 2니까 2/2 로 바꿀 수 있어. 여기에 1/2 을 더하면 3/2 이지. 그래서 자연수에 분모를 곱하고 분자를 더한 값을 새 분자로 쓰고, 분모는 그대로 두면 돼.", "again": "2와 3/4 을 가분수로 바꾸려고 해. 어떻게 하는지 말해 봐.", "fig": false, "src": "114쪽", "miscon": "자연수에 분모를 곱하지 않고 분자에 바로 더함", "record": "대분수를 가분수로 바꾸는 방법을 설명하지 못하거나 분모를 곱하는 과정을 빠뜨림"}, {"kind": "함정", "q": "자연수끼리 분수끼리 더했더니 분수 부분이 24/20 처럼 1보다 커졌어. 어떻게 마무리해야 하는지 말해 봐.", "ideas": [["분수 부분을 대분수로 바꿔서 1을 자연수 쪽으로 올린다", "24/20 은 1보다 큰데, 그 1을 어디로 보내야 돼?"], ["남은 분수 부분은 약분해서 기약분수로 만든다", "1을 올리고 남은 4/20 은 더 간단히 쓸 수 있어?"]], "teach": "24/20 은 1과 4/20 이야. 그 1을 자연수 쪽으로 올려서 자연수를 하나 늘리고, 남은 4/20 은 약분해서 1/5 로 써. 그래서 답이 3과 1/5 이 되는 거야.", "again": "자연수끼리 분수끼리 더했더니 분수 부분이 12/10 이 됐어. 어떻게 마무리해야 할지 말해 봐.", "fig": false, "src": "114쪽", "miscon": "대분수의 분수 부분이 1보다 커도 된다고 생각함", "record": "분수 부분이 1보다 클 때 자연수로 올리고 약분해 마무리하는 것을 설명하지 못함"}], "e5-1|5. 분수의 덧셈과 뺄셈|03. 분수의 뺄셈 (1)": [{"kind": "연결", "q": "분모가 다른 분수의 뺄셈은 덧셈이랑 어디가 같고 어디가 달라? 말해 봐.", "ideas": [["먼저 통분해서 분모를 같게 만드는 것은 덧셈과 똑같다", "5/6 − 1/4 을 바로 뺄 수 있어? 먼저 무엇을 해야 돼?"], ["분모가 같아진 뒤에 분자끼리 빼는 것만 다르다", "통분을 마친 다음 덧셈에서는 분자끼리 더했지? 뺄셈에서는 뭘 해?"]], "teach": "분모가 다르면 한 칸 크기가 달라서 바로 뺄 수 없는 건 덧셈과 똑같아. 그래서 먼저 통분해. 다른 건 분모가 같아진 다음에 분자끼리 더하지 않고 빼는 것뿐이야.", "again": "1/2 − 1/5 을 계산하려고 해. 덧셈과 같은 부분이 무엇이고 다른 부분이 무엇인지 말해 봐.", "fig": false, "src": "116쪽", "miscon": "뺄셈에서는 통분이 필요 없다고 생각함", "record": "분수의 뺄셈도 통분이 먼저라는 것을 덧셈과 견주어 설명하지 못함"}, {"kind": "전략", "q": "5/6 − 1/4 을 계산할 때 공통분모를 24로 해도 되고 12로 해도 돼. 결과가 달라질까? 어느 쪽이 편한지도 말해 봐.", "ideas": [["어느 공통분모로 해도 결과는 같다", "공통분모를 다르게 잡으면 분수의 크기 자체가 달라져?"], ["최소공배수인 12로 하면 수가 작고 약분할 일이 적어 편하다", "24로 하면 답이 14/24 로 나오는데 그다음에 뭘 더 해야 돼?"]], "teach": "공통분모를 무엇으로 잡아도 분수의 크기는 그대로라서 답은 같아. 다만 24로 하면 14/24 가 나와서 약분을 한 번 더 해야 하고, 최소공배수 12로 하면 바로 7/12 이 나와서 편해.", "again": "3/4 − 7/10 을 계산할 때 공통분모를 40으로 할 때와 20으로 할 때 무엇이 다른지 말해 봐.", "fig": false, "src": "116쪽", "miscon": "공통분모의 크기가 답의 크기를 바꾼다고 생각함", "record": "공통분모를 달리 잡아도 답이 같다는 것과, 최소공배수가 편한 까닭을 설명하지 못함"}], "e5-1|5. 분수의 덧셈과 뺄셈|04. 분수의 뺄셈 (2), (3)": [{"kind": "방법", "q": "대분수끼리 뺄 때 계산을 시작하기 전에 무엇을 먼저 확인해야 하는지 말해 봐.", "ideas": [["두 분수 부분의 크기를 먼저 비교한다", "2와 1/4 빼기 1과 1/2 에서 1/4 과 1/2 중에 어느 쪽이 커?"], ["앞의 분수 부분이 더 작으면 받아내림이 필요하다", "앞의 분수가 뒤의 분수보다 작으면 분수끼리 그냥 뺄 수 있어?"]], "teach": "먼저 두 분수 부분의 크기를 견줘 봐. 앞쪽이 더 크면 분수끼리 그냥 뺄 수 있어서 받아내림이 없어. 앞쪽이 더 작으면 분수끼리 뺄 수 없으니까 받아내림이 필요해.", "again": "3과 1/5 빼기 1과 2/3 을 계산하려고 해. 시작하기 전에 무엇을 확인해야 할지 말해 봐.", "fig": false, "src": "118쪽", "miscon": "자연수 부분만 보고 받아내림이 필요한지 판단함", "record": "대분수 뺄셈에서 분수 부분의 크기를 먼저 견주어야 한다는 것을 설명하지 못함"}, {"kind": "방법", "q": "받아내림이 없는 대분수 뺄셈은 어떻게 계산하는 게 편한지 말해 봐.", "ideas": [["자연수는 자연수끼리 뺀다", "대분수를 두 부분으로 나눠 보면 자연수끼리는 어떻게 해?"], ["분수 부분은 통분해서 분수끼리 뺀다", "분수 부분은 분모가 다른데 바로 뺄 수 있어?"]], "teach": "받아내림이 없으면 자연수는 자연수끼리 빼고, 분수 부분은 통분한 다음 분수끼리 빼면 편해. 2와 1/2 빼기 1과 2/5 이면 자연수 2−1, 분수 5/10−4/10 을 따로 계산하는 거야.", "again": "3과 3/4 빼기 1과 1/3 을 받아내림 없이 계산하려고 해. 어떤 차례로 하는지 말해 봐.", "fig": false, "src": "118쪽", "miscon": "분수 부분을 통분하지 않고 바로 분자끼리 뺌", "record": "받아내림이 없을 때 자연수·분수를 나눠 계산하는 방법을 설명하지 못하거나 통분을 빠뜨림"}, {"kind": "방법", "q": "앞의 분수 부분이 더 작아서 분수끼리 뺄 수 없을 때는 어떻게 계산해? 두 가지 방법을 말해 봐.", "ideas": [["대분수를 가분수로 바꿔서 계산한다", "자연수와 분수를 따로 떼지 않으려면 무엇으로 고치면 돼?"], ["또는 자연수에서 1을 받아내려 분수 부분을 크게 만든 뒤 뺀다", "분수 부분이 모자라면 어디에서 빌려 올 수 있어?"]], "teach": "두 가지가 있어. 대분수를 가분수로 바꿔서 통분해 빼는 방법이 하나고, 자연수에서 1을 받아내려 분수 부분을 크게 만든 다음 자연수끼리 분수끼리 빼는 방법이 또 하나야.", "again": "3과 1/6 빼기 1과 2/3 처럼 분수 부분이 모자랄 때 어떻게 계산할 수 있는지 방법을 말해 봐.", "fig": false, "src": "118쪽", "miscon": "작은 분수에서 큰 분수를 못 빼니까 순서를 거꾸로 바꿔 빼 버림", "record": "받아내림이 있을 때 쓰는 방법(가분수로 바꾸기 / 자연수에서 1 받아내리기)을 설명하지 못함"}, {"kind": "이유", "q": "2와 1/4 에서 자연수 1을 받아내리면 분수 부분이 5/4 가 돼. 왜 그렇게 되는지 말해 봐.", "ideas": [["받아내린 1을 분모가 4인 4/4 로 바꾼다", "분모가 4일 때 자연수 1은 몇 분의 몇이야?"], ["원래 있던 1/4 과 더해서 5/4 가 된다", "4/4 랑 원래 있던 1/4 을 합치면 얼마가 돼?"]], "teach": "자연수 1은 분모가 4일 때 4/4 야. 자연수 2에서 1을 빌려 와 4/4 로 바꾸고, 원래 있던 1/4 과 더하면 5/4 가 돼. 그래서 2와 1/4 은 1과 5/4 로도 쓸 수 있어.", "again": "3과 2/5 에서 자연수 1을 받아내리면 분수 부분이 얼마가 될까? 왜 그렇게 되는지 말해 봐.", "fig": false, "src": "118쪽", "miscon": "받아내린 1을 분모에 맞춘 분수로 바꾸지 않고 그대로 더함", "record": "받아내림에서 자연수 1을 분모에 맞춘 분수로 바꿔 더한다는 것을 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|01. 정다각형과 사각형의 둘레": [{"kind": "방법", "q": "정다각형의 둘레는 어떻게 구해? 왜 그렇게 구할 수 있는지도 말해 봐.", "ideas": [["둘레는 도형의 모든 변의 길이를 더한 것이다", "둘레라는 게 도형의 어느 부분을 잰 길이야?"], ["정다각형은 모든 변의 길이가 같아서 (한 변의 길이)×(변의 수)로 구할 수 있다", "변의 길이가 다 같으면 일일이 더하는 대신 무슨 계산을 하면 돼?"]], "teach": "둘레는 도형의 테두리를 한 바퀴 돈 길이, 곧 모든 변의 길이를 더한 거야. 정다각형은 변의 길이가 모두 같으니까 한 변의 길이에 변의 수를 곱하면 한 번에 구할 수 있어.", "again": "정육각형의 둘레를 구하려고 해. 어떻게 구하는지, 왜 그렇게 되는지 말해 봐.", "fig": false, "src": "140쪽", "miscon": "변의 수를 세지 않고 사각형처럼 항상 4를 곱함", "record": "둘레를 '모든 변의 길이의 합'으로 설명하지 못하거나, 정다각형에서 변의 수를 곱한다는 것을 말하지 못함"}, {"kind": "방법", "q": "직사각형의 둘레를 구하는 방법을 말해 봐. 왜 2배를 하는지도 얘기해 봐.", "ideas": [["직사각형은 마주 보는 두 변의 길이가 같다", "직사각형에서 가로는 몇 개고 세로는 몇 개야?"], ["그래서 가로와 세로를 더한 뒤 2배 하면 둘레가 된다", "가로와 세로를 한 번씩만 더하면 네 변을 다 센 게 될까?"]], "teach": "직사각형은 마주 보는 변끼리 길이가 같아서 가로가 2개, 세로가 2개야. 그래서 가로와 세로를 한 번씩 더한 다음 2배 하면 네 변을 모두 더한 것과 같아져.", "again": "가로가 7 cm, 세로가 3 cm 인 직사각형의 둘레를 어떻게 구하는지, 왜 그런지 말해 봐.", "fig": false, "src": "140쪽", "miscon": "둘레 구하는 데 넓이 공식을 씀", "record": "직사각형 둘레를 구하는 방법을 말하지 못하거나, 2배 하는 까닭을 설명하지 못함"}, {"kind": "방법", "q": "평행사변형이랑 마름모의 둘레는 각각 어떻게 구해? 왜 그렇게 되는지도 말해 봐.", "ideas": [["평행사변형은 마주 보는 변의 길이가 같아서 (한 변)+(다른 한 변)을 2배 한다", "평행사변형에서 길이가 같은 변끼리 묶으면 몇 개씩 짝이 돼?"], ["마름모는 네 변의 길이가 모두 같아서 (한 변)×4 를 한다", "마름모는 변의 길이가 몇 가지야?"]], "teach": "평행사변형은 마주 보는 변끼리 길이가 같아서 서로 다른 두 변을 더하고 2배 하면 돼. 마름모는 네 변이 모두 같으니까 한 변의 길이에 4를 곱하면 되지.", "again": "마름모의 둘레와 평행사변형의 둘레를 구하는 방법이 어떻게 다른지, 왜 다른지 말해 봐.", "fig": false, "src": "140쪽", "miscon": "평행사변형의 네 변이 모두 같다고 생각함", "record": "평행사변형과 마름모의 둘레 구하는 법을 변의 길이 성질과 연결해 설명하지 못함"}, {"kind": "함정", "q": "가로가 5 cm, 세로가 3 cm 인 직사각형의 둘레를 5+3=8 이라고 구한 친구가 있어. 뭐가 잘못됐는지 말해 봐.", "ideas": [["직사각형에는 가로와 세로가 각각 두 개씩 있다", "5+3 은 변을 몇 개 더한 거야? 직사각형의 변은 모두 몇 개야?"], ["그래서 (가로+세로)를 2배 해야 네 변을 다 센 것이 된다", "네 변을 모두 더한 값이 되려면 어떻게 고쳐야 돼?"]], "teach": "5+3 은 변 두 개만 더한 거야. 직사각형은 변이 네 개고 가로와 세로가 각각 두 개씩이니까, (5+3)을 2배 해야 네 변을 다 더한 게 돼.", "again": "가로가 6 cm, 세로가 4 cm 인 직사각형의 둘레를 6+4=10 이라고 한 친구가 있어. 어디가 틀렸는지 말해 봐.", "fig": false, "src": "140쪽", "miscon": "둘레를 가로와 세로를 한 번씩만 더한 값으로 생각함", "record": "직사각형의 변이 네 개이므로 (가로+세로)를 2배 해야 한다는 것을 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|02. 1 cm²": [{"kind": "이유", "q": "두 도형을 직접 맞대 보면 어느 쪽이 더 넓은지는 알 수 있어. 그런데 얼마나 넓은지는 왜 모를까? 정확히 알려면 무엇이 필요한지도 말해 봐.", "ideas": [["맞대 보는 것만으로는 얼마나 더 넓은지를 수로 나타낼 수 없다", "맞대 보면 '더 넓다'는 건 알겠는데, 얼마나 넓은지도 알 수 있어?"], ["기준이 되는 넓이의 단위가 있어야 수로 나타낼 수 있다", "길이를 잴 때 자에 눈금이 있는 것처럼, 넓이에도 무엇이 필요할까?"]], "teach": "맞대 보면 어느 쪽이 넓은지는 보이지만 얼마나 넓은지는 수로 말할 수 없어. 길이를 잴 때 1 cm 같은 단위를 쓰듯이, 넓이도 기준이 되는 단위가 있어야 수로 나타낼 수 있어.", "again": "책상 두 개 중 어느 쪽이 더 넓은지 눈으로 보고 골랐어. 얼마나 더 넓은지 말하려면 무엇이 필요할까? 왜 그런지도 말해 봐.", "fig": false, "src": "142쪽", "miscon": "겹쳐 보는 것만으로 넓이를 정확히 잴 수 있다고 생각함", "record": "넓이를 수로 나타내려면 기준 단위가 필요하다는 것을 설명하지 못함"}, {"kind": "함정", "q": "동그라미 모양을 단위로 써서 넓이를 재려고 했더니 잘 안 됐어. 왜 그럴까?", "ideas": [["동그라미는 도형을 빈틈없이 덮을 수 없다", "동그라미를 나란히 놓으면 사이사이에 뭐가 생겨?"], ["넓이의 단위는 빈틈없이 덮을 수 있는 모양이어야 한다", "빈틈이 생기면 개수를 세도 넓이를 정확히 알 수 있을까?"]], "teach": "동그라미를 아무리 촘촘히 놓아도 사이사이에 빈틈이 생겨. 빈틈이 있으면 몇 개인지 세도 넓이를 정확히 알 수 없지. 그래서 넓이의 단위는 빈틈없이 딱 맞게 덮을 수 있는 모양이어야 해.", "again": "넓이의 단위로 정사각형을 쓰고 동그라미는 안 쓰는 까닭이 뭘까? 말해 봐.", "fig": false, "src": "142쪽", "miscon": "단위 모양의 크기가 문제라고 생각하고 빈틈을 못 봄", "record": "넓이의 단위가 빈틈없이 덮을 수 있어야 한다는 조건을 설명하지 못함"}, {"kind": "뜻", "q": "1 cm² 가 뭔지 말해 봐. 어떻게 읽는지도 얘기해 봐.", "ideas": [["한 변의 길이가 1 cm 인 정사각형의 넓이다", "1 cm² 는 어떤 도형의 넓이를 말하는 거야?"], ["1 제곱센티미터라고 읽는다", "1 cm² 를 소리 내어 읽으면 뭐라고 해?"]], "teach": "1 cm² 는 한 변의 길이가 1 cm 인 정사각형의 넓이야. 읽을 때는 1 제곱센티미터라고 읽어. 이 정사각형이 몇 개 들어가는지 세면 넓이를 수로 나타낼 수 있어.", "again": "1 cm² 가 어떤 도형의 넓이인지, 뭐라고 읽는지 말해 봐.", "fig": false, "src": "142쪽", "miscon": "넓이의 단위를 길이의 단위와 섞어서 이해함", "record": "1 cm² 를 '한 변이 1 cm 인 정사각형의 넓이'로 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|03. 직사각형의 넓이": [{"kind": "이유", "q": "직사각형의 넓이는 (가로)×(세로)로 구해. 왜 그렇게 되는지 1 cm² 를 가지고 설명해 봐.", "ideas": [["한 줄에 1 cm² 가 가로의 길이만큼 놓인다", "가로가 4 cm 이면 한 줄에 1 cm² 가 몇 개 들어가?"], ["그런 줄이 세로의 길이만큼 있어서 가로와 세로를 곱하면 전체 개수가 된다", "그런 줄이 세로 길이만큼 쌓이면 전부 몇 개인지 어떻게 세?"]], "teach": "가로가 4 cm 면 한 줄에 1 cm² 가 4개 놓여. 세로가 3 cm 면 그런 줄이 3줄이지. 그래서 4×3=12, 넓이는 12 cm² 야. 곱셈은 하나씩 세는 걸 빠르게 한 거야.", "again": "가로가 5 cm, 세로가 2 cm 인 직사각형의 넓이를 왜 곱셈으로 구할 수 있는지 1 cm² 로 설명해 봐.", "fig": false, "src": "144쪽", "miscon": "넓이를 구하는 데 덧셈을 씀(둘레와 섞음)", "record": "직사각형 넓이 공식을 1 cm² 가 몇 줄로 놓이는지로 설명하지 못함"}, {"kind": "연결", "q": "정사각형의 넓이는 어떻게 구해? 직사각형 공식이랑 어떤 관계인지도 말해 봐.", "ideas": [["정사각형도 직사각형이라서 (가로)×(세로)로 구할 수 있다", "정사각형은 네 각이 모두 직각이지? 그럼 직사각형이라고 할 수 있을까?"], ["가로와 세로가 같으므로 (한 변)×(한 변)으로 쓴다", "정사각형은 가로랑 세로가 어때? 그럼 공식을 어떻게 바꿔 쓸 수 있어?"]], "teach": "정사각형도 네 각이 모두 직각이라 직사각형이야. 그래서 (가로)×(세로)로 구할 수 있어. 다만 가로와 세로가 같으니까 (한 변)×(한 변)이라고 써도 같은 뜻이야.", "again": "한 변이 6 cm 인 정사각형의 넓이를 어떻게 구하는지, 직사각형 공식과 어떻게 이어지는지 말해 봐.", "fig": false, "src": "144쪽", "miscon": "정사각형을 직사각형에 넣지 않고 따로 된 도형으로 봄", "record": "정사각형이 직사각형이므로 같은 공식을 쓴다는 연결을 설명하지 못함"}, {"kind": "함정", "q": "가로가 4 cm, 세로가 3 cm 인 직사각형의 둘레와 넓이는 뭐가 다른지 말해 봐.", "ideas": [["둘레는 테두리의 길이라서 변의 길이를 더해서 구한다", "둘레는 도형의 어느 부분을 잰 거야?"], ["넓이는 안쪽이 얼마나 넓은지라서 가로와 세로를 곱해서 구한다", "넓이는 도형의 어느 부분을 나타내는 거야?"]], "teach": "둘레는 도형의 테두리를 한 바퀴 돈 길이라서 변의 길이를 더해. 넓이는 도형 안쪽이 얼마나 넓은지라서 1 cm² 가 몇 개 들어가는지를 보고 가로와 세로를 곱해. 재는 대상이 아예 달라.", "again": "한 변이 5 cm 인 정사각형의 둘레와 넓이가 무엇이 다른지 말해 봐.", "fig": false, "src": "144쪽", "miscon": "둘레와 넓이를 구분하지 못하고 공식을 섞어 씀", "record": "둘레와 넓이가 각각 무엇을 재는지 구분해 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|04. 1 cm²보다 큰 넓이의 단위": [{"kind": "이유", "q": "1 cm² 말고 더 큰 넓이의 단위가 왜 필요한지 말해 봐.", "ideas": [["넓은 곳을 1 cm² 로 나타내면 수가 너무 커져서 불편하다", "가로 600 cm, 세로 300 cm 인 곳의 넓이를 cm² 로 쓰면 몇 자리 수가 돼?"], ["그래서 1 m², 1 km² 같은 더 큰 단위를 쓴다", "수를 간단하게 쓰려면 무엇을 바꿔야 돼?"]], "teach": "가로 600 cm, 세로 300 cm 인 곳의 넓이는 180000 cm² 야. 자릿수가 너무 많아서 읽기도 쓰기도 불편하지. 그래서 더 큰 단위인 1 m² 나 1 km² 를 만들어 쓰는 거야.", "again": "운동장의 넓이를 cm² 로 나타내면 무엇이 불편할까? 그래서 어떻게 하는지 말해 봐.", "fig": false, "src": "146쪽", "miscon": "큰 단위가 없으면 잴 수 없다고 생각함(불편함과 불가능을 섞음)", "record": "큰 넓이 단위가 필요한 까닭을 '수가 너무 커져 불편하다'로 설명하지 못함"}, {"kind": "뜻", "q": "1 m² 가 뭔지 말해 봐. 1 km² 도 같이 얘기해 봐.", "ideas": [["1 m² 는 한 변의 길이가 1 m 인 정사각형의 넓이다", "1 m² 는 어떤 정사각형의 넓이를 말하는 거야?"], ["1 km² 는 한 변의 길이가 1 km 인 정사각형의 넓이다", "1 km² 는 한 변이 얼마인 정사각형의 넓이일까?"]], "teach": "1 m² 는 한 변이 1 m 인 정사각형의 넓이이고 1 제곱미터라고 읽어. 1 km² 는 한 변이 1 km 인 정사각형의 넓이이고 1 제곱킬로미터라고 읽어. 만드는 방식은 1 cm² 와 똑같아.", "again": "1 m² 와 1 km² 가 각각 어떤 도형의 넓이인지 말해 봐.", "fig": false, "src": "146쪽", "miscon": "넓이 단위를 길이 단위로 이해함", "record": "1 m²·1 km² 를 '한 변이 1 m(1 km)인 정사각형의 넓이'로 설명하지 못함"}, {"kind": "이유", "q": "1 m² 는 10000 cm² 야. 1 m 가 100 cm 인데 왜 100 cm² 가 아닌지 말해 봐.", "ideas": [["1 m 가 100 cm 라서 한 줄에 1 cm² 가 100개 들어간다", "한 변이 1 m 인 정사각형의 한 줄에는 1 cm² 가 몇 개 놓여?"], ["그런 줄이 100줄 있어서 100×100=10000 개가 된다", "그런 줄이 몇 줄 쌓여 있어? 그럼 전부 몇 개야?"]], "teach": "한 변이 1 m 인 정사각형은 가로도 100 cm, 세로도 100 cm 야. 한 줄에 1 cm² 가 100개 놓이고 그런 줄이 100줄이니까 100×100=10000 개. 넓이는 가로와 세로 두 방향 모두 늘어나서 100배가 아니라 10000배가 되는 거야.", "again": "1 km² 가 1 m² 로 몇 개인지 알아보려면 어떻게 생각해야 할까? 까닭과 같이 말해 봐.", "fig": false, "src": "146쪽", "miscon": "넓이를 길이처럼 한 방향만 늘려 생각해 단위 환산을 100배로 함", "record": "넓이 단위 환산에서 가로·세로 두 방향이 모두 늘어난다는 것을 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|05. 평행사변형의 넓이": [{"kind": "뜻", "q": "평행사변형에서 밑변이랑 높이가 각각 뭔지 말해 봐.", "ideas": [["밑변은 평행한 두 변이다", "평행사변형에서 서로 평행한 변이 몇 쌍 있어? 그걸 뭐라고 불러?"], ["높이는 두 밑변 사이의 거리다", "밑변을 정하고 나면 높이는 어디를 잰 길이야?"]], "teach": "평행사변형에서 평행한 두 변을 밑변이라고 해. 높이는 그 두 밑변 사이의 거리야. 밑변을 어느 쪽으로 잡느냐에 따라 높이도 달라져.", "again": "평행사변형의 밑변을 정하면 높이는 어디를 재야 할까? 밑변이 무엇인지도 같이 말해 봐.", "fig": false, "src": "154쪽", "miscon": "높이를 옆의 비스듬한 변의 길이로 착각함", "record": "평행사변형의 밑변·높이의 뜻을 말하지 못하거나, 높이를 비스듬한 변으로 잘못 알고 있음"}, {"kind": "이유", "q": "평행사변형의 넓이가 (밑변의 길이)×(높이)인 까닭을 말해 봐.", "ideas": [["한쪽 끝을 높이를 따라 잘라 반대쪽에 붙이면 직사각형이 된다", "평행사변형을 잘라 옮겨 붙이면 어떤 도형이 돼?"], ["그 직사각형의 가로가 밑변, 세로가 높이라서 둘을 곱하면 된다", "만들어진 직사각형의 가로와 세로는 원래 무엇이었어?"]], "teach": "평행사변형의 한쪽 끝을 높이를 따라 잘라 반대쪽에 붙이면 딱 직사각형이 돼. 넓이는 그대로지. 그 직사각형의 가로가 밑변이고 세로가 높이니까 (밑변)×(높이)가 넓이야.", "again": "평행사변형을 직사각형으로 바꿔서 넓이를 구하는 방법을 말해 봐. 왜 넓이가 변하지 않는지도 얘기해 봐.", "fig": false, "src": "154쪽", "miscon": "넓이 공식을 외우지 못하고 변을 모두 곱하려 함", "record": "평행사변형 넓이 공식을 직사각형으로 바꾸는 과정으로 설명하지 못함"}, {"kind": "성질", "q": "밑변의 길이와 높이가 같으면 모양이 달라도 넓이가 같아. 왜 그런지 말해 봐.", "ideas": [["넓이는 밑변의 길이와 높이만으로 정해지기 때문이다", "넓이를 구할 때 쓰는 값이 무엇 무엇이야?"], ["기울어진 정도는 넓이에 영향을 주지 않는다", "많이 기울어진 평행사변형이랑 조금 기울어진 것이 밑변·높이가 같으면 넓이가 달라져?"]], "teach": "평행사변형의 넓이는 밑변과 높이만으로 정해져. 아무리 많이 기울어져 있어도 밑변의 길이와 높이가 같으면 잘라 붙였을 때 같은 직사각형이 되니까 넓이가 같아.", "again": "밑변이 4 cm, 높이가 3 cm 인 평행사변형을 여러 가지 모양으로 그렸어. 넓이가 어떨지 이유와 같이 말해 봐.", "fig": false, "src": "154쪽", "miscon": "기울어진 정도가 넓이를 바꾼다고 생각함", "record": "밑변과 높이가 같으면 넓이가 같다는 것을 공식과 연결해 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|06. 삼각형의 넓이": [{"kind": "뜻", "q": "삼각형에서 밑변이랑 높이가 각각 뭔지 말해 봐.", "ideas": [["밑변은 삼각형의 어느 한 변이고, 기준으로 정하는 변이다", "삼각형에서 밑변은 꼭 아래쪽 변이어야 해?"], ["높이는 밑변과 마주 보는 꼭짓점에서 밑변에 수직으로 그은 선분의 길이다", "높이를 그으려면 어느 점에서 출발해서 어떻게 그어?"]], "teach": "삼각형은 어느 변이든 밑변으로 정할 수 있어. 밑변을 정하면 그와 마주 보는 꼭짓점에서 밑변에 수직으로 그은 선분의 길이가 높이야. 밑변을 바꾸면 높이도 바뀌어.", "again": "삼각형에서 밑변을 다른 변으로 바꾸면 높이는 어떻게 될까? 밑변과 높이가 무엇인지도 말해 봐.", "fig": false, "src": "156쪽", "miscon": "높이를 이웃한 변의 길이로 착각함", "record": "삼각형의 높이를 '밑변과 마주 보는 꼭짓점에서 수직으로 그은 선분'으로 설명하지 못함"}, {"kind": "이유", "q": "삼각형의 넓이가 (밑변의 길이)×(높이)÷2 인 까닭을 말해 봐.", "ideas": [["똑같은 삼각형 2개를 붙이면 평행사변형이 된다", "같은 삼각형을 하나 더 만들어 돌려 붙이면 어떤 도형이 돼?"], ["삼각형은 그 평행사변형 넓이의 반이라서 2로 나눈다", "삼각형 하나는 그 평행사변형의 얼마만큼이야?"]], "teach": "똑같은 삼각형 2개를 돌려서 붙이면 평행사변형이 딱 만들어져. 그 평행사변형의 넓이는 (밑변)×(높이)인데 삼각형은 그 반이니까 2로 나누는 거야.", "again": "삼각형의 넓이를 구할 때 왜 2로 나누는지 말해 봐.", "fig": false, "src": "156쪽", "miscon": "나누는 수를 변의 개수로 생각함", "record": "삼각형 넓이에서 2로 나누는 까닭을 평행사변형과 이어서 설명하지 못함"}, {"kind": "함정", "q": "삼각형의 높이를 그릴 때 아무 선이나 그으면 안 돼. 어떻게 그어야 하는지 말해 봐.", "ideas": [["밑변과 마주 보는 꼭짓점에서 그어야 한다", "높이는 어느 점에서 출발해야 돼?"], ["밑변에 수직이 되게 그어야 한다", "비스듬하게 그은 선도 높이라고 할 수 있어?"]], "teach": "높이는 밑변과 마주 보는 꼭짓점에서 출발해서 밑변에 수직으로 그어야 해. 비스듬히 그은 선은 높이가 아니야. 밑변이 짧아서 삼각형 밖으로 나가는 경우에는 밑변을 늘여서 수직으로 그어.", "again": "삼각형의 높이를 그었는데 밑변에 수직이 아니었어. 무엇이 잘못됐는지 말해 봐.", "fig": false, "src": "156쪽", "miscon": "높이를 수직이 아닌 임의의 선으로 그음", "record": "높이를 긋는 두 조건(마주 보는 꼭짓점에서·밑변에 수직으로)을 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|07. 마름모의 넓이": [{"kind": "이유", "q": "마름모의 넓이가 (한 대각선의 길이)×(다른 대각선의 길이)÷2 인 까닭을, 직사각형을 이용해서 말해 봐.", "ideas": [["마름모를 둘러싸는 직사각형을 그리면 마름모는 그 직사각형 넓이의 반이다", "마름모를 감싸는 직사각형을 그리면 마름모는 그 안에서 얼마만큼을 차지해?"], ["그 직사각형의 가로와 세로가 두 대각선의 길이라서 곱하고 2로 나눈다", "감싼 직사각형의 가로와 세로는 마름모의 무엇과 길이가 같아?"]], "teach": "마름모를 딱 맞게 둘러싸는 직사각형을 그리면, 그 직사각형의 가로와 세로가 마름모의 두 대각선이야. 마름모는 그 직사각형의 반을 차지하니까 두 대각선을 곱하고 2로 나누면 넓이가 돼.", "again": "마름모를 직사각형으로 둘러싸서 넓이를 구하는 방법을 말해 봐. 왜 2로 나누는지도 얘기해 봐.", "fig": false, "src": "158쪽", "miscon": "대각선을 곱하지 않고 더해서 계산함", "record": "마름모 넓이 공식을 둘러싼 직사각형의 반으로 설명하지 못함"}, {"kind": "이유", "q": "마름모를 잘라서 평행사변형으로 만들어 넓이를 구하는 방법도 있어. 어떻게 되는지 말해 봐.", "ideas": [["대각선을 따라 잘라 옮겨 붙이면 평행사변형이 된다", "마름모를 어느 선을 따라 잘라 붙이면 평행사변형이 돼?"], ["그 평행사변형의 밑변은 한 대각선, 높이는 다른 대각선의 반이 된다", "만들어진 평행사변형의 밑변과 높이는 원래 무엇이었어?"]], "teach": "마름모를 한 대각선을 따라 잘라 옮겨 붙이면 평행사변형이 돼. 그 평행사변형의 밑변은 한 대각선이고 높이는 다른 대각선의 반이야. 그래서 넓이가 (한 대각선)×(다른 대각선÷2)가 되는 거야.", "again": "마름모를 평행사변형으로 바꿔서 넓이를 구했어. 바꾼 평행사변형의 밑변과 높이가 원래 마름모의 무엇이었는지 말해 봐.", "fig": false, "src": "158쪽", "miscon": "잘라 붙였을 때 높이가 대각선의 반이 되는 것을 놓침", "record": "마름모를 평행사변형으로 바꾸는 방법에서 밑변·높이가 무엇이 되는지 설명하지 못함"}, {"kind": "함정", "q": "마름모의 넓이를 구하는데 대각선이 아니라 한 변의 길이를 곱한 친구가 있어. 뭐가 잘못됐는지 말해 봐.", "ideas": [["마름모의 넓이 공식에는 변이 아니라 두 대각선의 길이가 들어간다", "마름모 넓이를 구할 때 쓰는 길이가 변이야, 대각선이야?"], ["변의 길이가 같아도 얼마나 납작한지에 따라 넓이가 달라진다", "변의 길이가 똑같은 마름모를 납작하게 눌러도 넓이가 그대로야?"]], "teach": "마름모 넓이는 두 대각선의 길이로 구해. 변의 길이만으로는 넓이를 알 수 없어. 변의 길이가 같아도 납작하게 눌리면 대각선이 달라져서 넓이가 작아지거든.", "again": "한 변이 5 cm 인 마름모가 여러 개 있는데 넓이가 다 달라. 어떻게 그럴 수 있는지 말해 봐.", "fig": false, "src": "158쪽", "miscon": "변의 길이만으로 마름모의 넓이가 정해진다고 생각함", "record": "마름모의 넓이가 변이 아니라 두 대각선으로 정해진다는 것을 설명하지 못함"}], "e5-1|6. 다각형의 둘레와 넓이|08. 사다리꼴의 넓이": [{"kind": "뜻", "q": "사다리꼴에서 윗변, 아랫변, 높이가 각각 뭔지 말해 봐.", "ideas": [["평행한 두 변이 밑변이고, 한쪽을 윗변 다른 쪽을 아랫변이라고 한다", "사다리꼴에서 서로 평행한 변은 몇 개야? 그걸 뭐라고 불러?"], ["높이는 두 밑변 사이의 거리다", "윗변과 아랫변을 정하고 나면 높이는 어디를 잰 길이야?"]], "teach": "사다리꼴에서 평행한 두 변이 밑변이야. 그중 한쪽을 윗변, 다른 쪽을 아랫변이라고 불러. 높이는 그 두 밑변 사이의 거리고, 비스듬한 변의 길이가 아니야.", "again": "사다리꼴의 높이는 어디를 재는 건지 말해 봐. 윗변과 아랫변이 무엇인지도 얘기해 봐.", "fig": false, "src": "160쪽", "miscon": "높이를 비스듬한 변의 길이로 착각함", "record": "사다리꼴의 윗변·아랫변·높이의 뜻을 설명하지 못하거나 높이를 옆변으로 잘못 앎"}, {"kind": "이유", "q": "사다리꼴의 넓이가 ((윗변의 길이)+(아랫변의 길이))×(높이)÷2 인 까닭을 말해 봐.", "ideas": [["똑같은 사다리꼴 2개를 돌려 붙이면 평행사변형이 된다", "같은 사다리꼴을 하나 더 만들어 뒤집어 붙이면 어떤 도형이 돼?"], ["그 평행사변형의 밑변이 윗변과 아랫변을 더한 길이라서, 넓이를 구한 뒤 2로 나눈다", "만들어진 평행사변형의 밑변 길이는 원래 무엇과 무엇을 더한 거야?"]], "teach": "똑같은 사다리꼴 2개를 뒤집어 붙이면 평행사변형이 돼. 그 평행사변형의 밑변은 윗변과 아랫변을 더한 길이이고 높이는 그대로야. 사다리꼴은 그 반이니까 2로 나누는 거야.", "again": "사다리꼴의 넓이를 구할 때 윗변과 아랫변을 왜 더하는지, 왜 2로 나누는지 말해 봐.", "fig": false, "src": "160쪽", "miscon": "두 밑변을 더하지 않고 곱해 버림", "record": "사다리꼴 넓이 공식을 평행사변형 2개로 만드는 과정으로 설명하지 못함"}, {"kind": "성질", "q": "윗변과 아랫변을 더한 길이가 같고 높이도 같으면 모양이 달라도 넓이가 같아. 왜 그런지 말해 봐.", "ideas": [["넓이는 두 밑변을 더한 길이와 높이만으로 정해진다", "넓이를 구할 때 쓰는 값이 무엇 무엇이야?"], ["윗변과 아랫변이 각각 얼마인지는 합만 같으면 넓이에 영향을 주지 않는다", "윗변 3 아랫변 3 일 때랑 윗변 4 아랫변 2 일 때, 합이 같으면 넓이가 달라져?"]], "teach": "공식에 들어가는 건 두 밑변을 '더한 길이'와 높이뿐이야. 그래서 윗변이 3 아랫변이 3 이든 윗변이 4 아랫변이 2 이든, 합이 6이고 높이가 같으면 넓이는 같아.", "again": "높이가 같은 두 사다리꼴이 있는데 윗변과 아랫변의 길이가 서로 달라. 넓이가 같을 수 있는지 이유와 같이 말해 봐.", "fig": false, "src": "160쪽", "miscon": "공식에 들어가는 값이 두 밑변의 합이라는 것을 못 봄", "record": "두 밑변의 합과 높이만으로 사다리꼴 넓이가 정해진다는 것을 설명하지 못함"}]});
